window.TREE={"subject":"Ethical and Professional Standards","key":"cfa_l1_ethics","brand":"Terra Prep","parts":[{"no":1,"name":"Ethical and Professional Standards","chs":["1-01"],"color":"--fam-geo"}],"chs":[{"key":"1-01","part":1,"no":1,"name":"Ethical and Professional Standards","nodes":[1,2,3,4,5,6,7]}],"nodes":[{"no":1,"part":1,"ch":1,"title":"Standard I: Professionalism","name":"Standard I: Professionalism","vol":16,"q":65,"cs":0,"law":0},{"no":2,"part":1,"ch":1,"title":"Standard II: Integrity of Capital Markets","name":"Standard II: Integrity of Capital Markets","vol":6,"q":26,"cs":0,"law":0},{"no":3,"part":1,"ch":1,"title":"Standard III: Duties to Clients","name":"Standard III: Duties to Clients","vol":16,"q":65,"cs":0,"law":0},{"no":4,"part":1,"ch":1,"title":"Standard IV: Duties to Employers","name":"Standard IV: Duties to Employers","vol":9,"q":39,"cs":0,"law":0},{"no":5,"part":1,"ch":1,"title":"Standard V: Investment Analysis, Recommendations, and Actions","name":"Standard V: Investment Analysis, Recommendations, and Actions","vol":9,"q":39,"cs":0,"law":0},{"no":6,"part":1,"ch":1,"title":"Standard VI: Conflicts of Interest","name":"Standard VI: Conflicts of Interest","vol":9,"q":39,"cs":0,"law":0},{"no":7,"part":1,"ch":1,"title":"Standard VII: Responsibilities as a CFA Institute Member or CFA Candidate","name":"Standard VII: Responsibilities as a CFA Institute Member or CFA Candidate","vol":6,"q":26,"cs":0,"law":0}],"stat":{"parts":1,"chs":1,"nodes":7,"q":299}};
window.QBANK={"3":[{"i":"CFAMC-III-001","t":"A member manages the assets of a company pension plan. According to the guidance under Standard III(A), to whom is the member's duty of loyalty owed?","c":"A","mc":{"s":"A member manages the assets of a company pension plan. According to the guidance under Standard III(A), to whom is the member's duty of loyalty owed?","d":"","o":["The company that established and hired the manager for the pension plan","The ultimate beneficiaries of the pension plan","The plan's board of directors exclusively, regardless of beneficiary interests"],"a":2,"cite":"Standard III(A)","rat":"The guidance states that when managing pension or trust assets, the client is not the hiring entity but the ultimate beneficiaries of the plan or trust, to whom loyalty is owed."}},{"i":"CFAMC-III-002","t":"A client directs her manager to use a specific brokerage firm for all of her trades, even though this may not achieve best execution. According to Standard III(A) guidance, this directed brokerage arrangement:","c":"A","mc":{"s":"A client directs her manager to use a specific brokerage firm for all of her trades, even though this may not achieve best execution. According to Standard III(A) guidance, this directed brokerage arrangement:","d":"","o":["Always violates the manager's duty of loyalty because best execution is mandatory in every case","Does not violate the duty of loyalty, but the manager should disclose that best execution may not be achieved","Is prohibited unless the client pays an additional fee to the manager"],"a":2,"cite":"Standard III(A)","rat":"The guidance states directed brokerage does not violate the duty of loyalty because the commission is the client's asset used for the client's benefit, but the manager should disclose that best execution may not result."}},{"i":"CFAMC-III-003","t":"According to the guidance under Standard III(A), an investment manager who routinely fails to vote proxies or votes them without considering the impact of nonroutine governance questions is MOST likely:","c":"A","mc":{"s":"According to the guidance under Standard III(A), an investment manager who routinely fails to vote proxies or votes them without considering the impact of nonroutine governance questions is MOST likely:","d":"","o":["In compliance, because proxy voting is entirely optional and unrelated to the duty of loyalty","In violation of Standard III(A), because proxies have economic value that must be safeguarded as part of the duty of loyalty","In violation only if the client explicitly requested that all proxies be voted"],"a":2,"cite":"Standard III(A)","rat":"The guidance treats informed, responsible proxy voting as part of the duty of loyalty because proxies have economic value for the client that must be safeguarded and maximized."}},{"i":"CFAOX-III-001","t":"Standard III(A) requires members and candidates to act for the benefit of clients and place client interests before those of their employer or themselves.","ox":"O","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard III(A)","rat":"This restates the text of Standard III(A)."},{"i":"CFAOX-III-002","t":"Standard III(A) automatically makes every member and candidate a legal fiduciary to their clients.","ox":"X","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard III(A)","rat":"The guidance states Standard III(A) does not render all members and candidates fiduciaries; fiduciary status depends on the facts, client type, and nature of the relationship."},{"i":"CFAOX-III-003","t":"When managing assets for a pension plan or trust, the duty of loyalty under Standard III(A) is owed to the ultimate beneficiaries rather than to the entity that hired the manager.","ox":"O","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard III(A)","rat":"The guidance specifically identifies plan or trust beneficiaries, not the hiring entity, as the client to whom loyalty is owed."},{"i":"CFAOX-III-004","t":"A member who pays a higher brokerage commission than necessary to obtain research services (soft dollars), without a corresponding benefit to the client, violates the duty of loyalty under Standard III(A).","ox":"O","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard III(A)","rat":"The guidance states that paying an unjustified higher commission for goods or services without corresponding client benefit violates the duty of loyalty."},{"i":"CFAOX-III-005","t":"A client-directed brokerage arrangement automatically violates a member's duty of loyalty under Standard III(A) because it may not achieve best execution.","ox":"X","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard III(A)","rat":"The guidance states directed brokerage does not violate the duty of loyalty since the commission is a client asset used for the client's benefit, though best execution limitations should be disclosed."},{"i":"CFAOX-III-006","t":"Under Standard III(A), an investment manager's duty regarding a particular holding is judged only by that single security's own risk and return, without reference to the overall portfolio.","ox":"X","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard III(A)","rat":"The guidance states investment decisions must be judged in the context of the total portfolio, considering diversification, liquidity, cash flow, and overall return requirements, not in isolation."},{"i":"CFAOX-III-007","t":"Members and candidates with custody of client assets should submit itemized account statements to clients at least quarterly.","ox":"O","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard III(A)","rat":"This is a compliance practice listed directly in the guidance for members with control of client assets."},{"i":"CFAOX-III-008","t":"Standard III(A) requires members and candidates to vote every proxy in every instance, regardless of cost or benefit to the client.","ox":"X","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard III(A)","rat":"The guidance notes a cost-benefit analysis may show voting all proxies does not benefit the client, so voting every proxy is not required in all instances."},{"i":"CFAOX-III-009","t":"Trade execution professionals who do not provide advisory services are exempt from the duty of loyalty, prudence, and care under Standard III(A).","ox":"X","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard III(A)","rat":"The guidance states execution-only professionals must still prudently act in the client's interest by seeking the most favorable terms achievable within the client's instructions."},{"i":"CFAOX-III-010","t":"Members and candidates who cannot avoid a potential conflict between their firm's interests and a client's interests must provide clear and factual disclosure of the circumstances to the client.","ox":"O","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard III(A)","rat":"The guidance requires clear, factual disclosure of unavoidable conflicts between firm and client interests."},{"i":"CFAMC-III-004","t":"An analyst mentions his firm's upcoming purchase recommendation to several of his best clients over lunch, a week before the report is sent to all clients. This is BEST described as a violation of Standard III(B) because:","c":"A","mc":{"s":"An analyst mentions his firm's upcoming purchase recommendation to several of his best clients over lunch, a week before the report is sent to all clients. This is BEST described as a violation of Standard III(B) because:","d":"","o":["Standard III(B) requires that recommendations be communicated to all clients equally rather than fairly","Selectively disclosing the recommendation to favored clients in advance denies other clients a fair opportunity to act on it","Analysts are never permitted to discuss research with clients before publication under any circumstances"],"a":2,"cite":"Standard III(B)","rat":"The guidance requires that all clients have a fair opportunity to act on a recommendation; disclosing it early to select favored clients is a violation, as illustrated in the Ames example."}},{"i":"CFAMC-III-005","t":"A bank's pension fund manager, as a matter of policy, always purchases new recommended securities for the bank's commingled fund first and only later allocates remaining shares pro rata to other pension accounts, giving nondiscretionary and personal trust accounts the lowest priority. According to Standard III(B), this practice is BEST described as:","c":"A","mc":{"s":"A bank's pension fund manager, as a matter of policy, always purchases new recommended securities for the bank's commingled fund first and only later allocates remaining shares pro rata to other pension accounts, giving nondiscretionary and personal trust accounts the lowest priority. According to Standard III(B), this practice is BEST described as:","d":"","o":["Acceptable, because the commingled fund's superior historical performance justifies prioritizing it","A violation, because systematically prioritizing one fund and account type over others fails to treat all clients fairly","Acceptable, as long as the policy is disclosed to prospective clients before they invest"],"a":2,"cite":"Standard III(B)","rat":"The guidance concludes that consistently favoring one commingled fund and account category over others is a violation of the duty to deal fairly with all clients, regardless of disclosure."}},{"i":"CFAMC-III-006","t":"When a new issue offered to a firm's clients is oversubscribed, Standard III(B) guidance indicates that members and candidates should MOST appropriately:","c":"A","mc":{"s":"When a new issue offered to a firm's clients is oversubscribed, Standard III(B) guidance indicates that members and candidates should MOST appropriately:","d":"","o":["Fill their own and immediate family members' orders first, since they bear the same investment risk as other clients","Prorate the issue among all suitable client accounts and forgo sales to themselves or immediate family to free up shares for clients","Allocate the full amount to whichever clients placed their orders first, regardless of suitability"],"a":2,"cite":"Standard III(B)","rat":"The guidance requires prorating an oversubscribed issue among suitable accounts and forgoing sales to the member's own or immediate family accounts to free up additional shares for clients."}},{"i":"CFAOX-III-011","t":"Standard III(B) requires members and candidates to deal fairly and objectively with all clients when providing investment analysis, making recommendations, or taking investment action.","ox":"O","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard III(B)","rat":"This restates the text of Standard III(B)."},{"i":"CFAOX-III-012","t":"Standard III(B) requires that all clients be treated exactly equally, receiving identical services at identical times.","ox":"X","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard III(B)","rat":"The guidance uses the word \"fairly\" rather than \"equally,\" recognizing that members cannot reach all clients simultaneously and may offer differentiated service levels as long as this is disclosed and does not disadvantage clients."},{"i":"CFAOX-III-013","t":"Members and candidates may offer premium, more in-depth service to clients willing to pay for it, provided the different service levels are disclosed and available to all clients.","ox":"O","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard III(B)","rat":"The guidance permits differentiated service levels as long as they are disclosed and offered on a non-selective basis, without disadvantaging other clients."},{"i":"CFAOX-III-014","t":"When a member changes a prior investment recommendation, only new clients need to be informed of the change; existing clients who already acted on the earlier advice may be left uninformed.","ox":"X","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard III(B)","rat":"The guidance requires material changes in recommendations to be communicated to all current clients, with particular care for those known to have acted on the earlier advice."},{"i":"CFAOX-III-015","t":"If a new issue is oversubscribed, Standard III(B) guidance requires prorating the shares to suitable client accounts and forgoing sales to the member's own or immediate family's accounts.","ox":"O","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard III(B)","rat":"This is stated directly in the guidance on investment action and new offerings."},{"i":"CFAOX-III-016","t":"If a member's family-member accounts are managed in the same manner as other client accounts, those family accounts must nonetheless always be excluded from buying shares in an oversubscribed offering.","ox":"X","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard III(B)","rat":"The guidance states family-member accounts managed similarly to other client accounts must not be excluded from buying such shares."},{"i":"CFAOX-III-017","t":"Client consent to a patently unfair trade allocation procedure relieves the member of the duty of fair dealing under Standard III(B).","ox":"X","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard III(B)","rat":"The guidance states the duty of fairness and loyalty can never be overridden by client consent to patently unfair allocation procedures."},{"i":"CFAOX-III-018","t":"A recommended compliance practice under Standard III(B) is to give all client accounts participating in a block trade the same execution price and the same commission.","ox":"O","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard III(B)","rat":"This is listed directly among the trade allocation practices in the compliance guidance."},{"i":"CFAOX-III-019","t":"Disclosing an inequitable trade allocation method to clients satisfies Standard III(B), because disclosure alone cures any unfairness in the procedure.","ox":"X","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard III(B)","rat":"The guidance explicitly states that disclosure of inequitable allocation methods does not relieve the member of the obligation to have fair and equitable procedures."},{"i":"CFAOX-III-020","t":"Members and candidates should make reasonable efforts to limit both the number of people aware of a pending recommendation and the time between the decision and its dissemination.","ox":"O","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard III(B)","rat":"Both practices are listed among the compliance practices for fair dealing in disseminating recommendations."},{"i":"CFAMC-III-007","t":"An adviser recommends the same 20% allocation to zero-yield, small-cap, high-technology equities for two very different clients: an aggressive, wealthy client and a conservative client seeking steady, low-volatility returns to fund a specific future need. According to Standard III(C) guidance, this recommendation is BEST described as:","c":"A","mc":{"s":"An adviser recommends the same 20% allocation to zero-yield, small-cap, high-technology equities for two very different clients: an aggressive, wealthy client and a conservative client seeking steady, low-volatility returns to fund a specific future need. According to Standard III(C) guidance, this recommendation is BEST described as:","d":"","o":["Suitable for both clients, since the same investment cannot be judged differently across clients","Potentially suitable for the aggressive client but unsuitable for the conservative client, given their differing risk profiles and objectives","A violation of Standard III(B) Fair Dealing rather than Standard III(C), since both clients received the identical recommendation"],"a":2,"cite":"Standard III(C)","rat":"Standard III(C) requires suitability to be judged against each client's own risk tolerance, objectives, and constraints; the same investment can be appropriate for one client and unsuitable for another."}},{"i":"CFAMC-III-008","t":"A fund manager runs a large-cap income fund to a stated mandate and receives purchase orders from investors who buy shares directly in the fund. According to the guidance under Standard III(C), the fund manager's suitability obligation is BEST described as:","c":"A","mc":{"s":"A fund manager runs a large-cap income fund to a stated mandate and receives purchase orders from investors who buy shares directly in the fund. According to the guidance under Standard III(C), the fund manager's suitability obligation is BEST described as:","d":"","o":["The manager must individually assess the suitability of the fund for every investor who purchases shares","The manager must invest consistently with the fund's stated mandate but is not responsible for determining suitability for individual fund purchasers absent an advisory relationship","The manager has no suitability obligations at all, even with respect to the fund's stated mandate"],"a":2,"cite":"Standard III(C)","rat":"The guidance states that managers of a fund to a specific mandate must invest consistently with that mandate, but suitability determinations for individual investors apply only where an advisory relationship exists."}},{"i":"CFAMC-III-009","t":"A client insists on an unsolicited trade that the adviser knows is inconsistent with the client's written investment policy statement, and the client declines to update the policy statement. According to Standard III(C) guidance, the adviser should MOST appropriately:","c":"A","mc":{"s":"A client insists on an unsolicited trade that the adviser knows is inconsistent with the client's written investment policy statement, and the client declines to update the policy statement. According to Standard III(C) guidance, the adviser should MOST appropriately:","d":"","o":["Execute the trade immediately without discussion, since client instructions always override the adviser's suitability analysis","Discuss the concerns with the client, document that the trade is against advice, and evaluate whether to continue the advisory relationship","Refuse to ever execute the trade under any circumstances, even after full disclosure and client acknowledgment"],"a":2,"cite":"Standard III(C)","rat":"The guidance describes discussing concerns, documenting client acknowledgment that the trade is against advice, and evaluating whether to continue the advisory relationship as the appropriate response to an insisted unsuitable trade."}},{"i":"CFAOX-III-021","t":"Standard III(C) requires members and candidates in an advisory relationship to make a reasonable inquiry into a client's investment experience, risk and return objectives, and financial constraints before making a recommendation or taking investment action.","ox":"O","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard III(C)","rat":"This restates the requirement of Standard III(C)(1)(a)."},{"i":"CFAOX-III-022","t":"Suitability under Standard III(C) must be judged for each individual holding in isolation, without reference to the client's total portfolio.","ox":"X","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard III(C)","rat":"Standard III(C)(1)(c) requires judging the suitability of investments in the context of the client's total portfolio."},{"i":"CFAOX-III-023","t":"A properly conducted suitability analysis guarantees that a recommended investment will not lose value.","ox":"X","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard III(C)","rat":"The guidance states an appropriate suitability determination will not, however, prevent some investments from losing value."},{"i":"CFAOX-III-024","t":"Best practice under Standard III(C) is to incorporate client information into a written investment policy statement addressing risk tolerance, return requirements, and relevant investment limitations.","ox":"O","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard III(C)","rat":"This is stated directly in the guidance on developing an investment policy."},{"i":"CFAOX-III-025","t":"An investment policy statement, once created at the start of an advisory relationship, need never be updated as long as the client does not initiate contact.","ox":"X","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard III(C)","rat":"The guidance states an IPS should be reviewed at least annually and prior to material changes in recommendations, since client circumstances change over time."},{"i":"CFAOX-III-026","t":"If a client withholds information about parts of their financial portfolio not managed by the adviser, the adviser's suitability analysis must be based only on the information actually provided.","ox":"O","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard III(C)","rat":"The guidance states the suitability analysis cannot be expected to be complete if clients withhold information, and must be based on what is actually provided."},{"i":"CFAOX-III-027","t":"A member managing a fund to a stated large-cap income mandate satisfies Standard III(C) by investing heavily in speculative small-cap start-ups whenever such investments could produce higher returns.","ox":"X","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard III(C)","rat":"The guidance states a manager of a fund to a mandate must invest consistently with the stated mandate; investing outside that mandate, such as heavily in small-cap start-ups for a large-cap income fund, would not comply."},{"i":"CFAOX-III-028","t":"When a client insists on an unsolicited trade the adviser knows is unsuitable, the adviser should require the client to acknowledge that the trade is being made against the adviser's advice.","ox":"O","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard III(C)","rat":"The guidance recommends requiring client acknowledgment of the discussion and that the trade is contrary to advice."},{"i":"CFAOX-III-029","t":"Members and candidates who are merely executing specific client instructions to buy or sell securities, without an advisory relationship, bear the same suitability determination duty as investment advisers.","ox":"X","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard III(C)","rat":"The guidance states the duty to conduct a suitability analysis falls on those in an advisory relationship; those merely executing specific instructions may not have the opportunity to judge suitability."},{"i":"CFAOX-III-030","t":"An investment with high relative risk on its own can still be suitable when considered in the context of the client's entire portfolio or stated objectives.","ox":"O","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard III(C)","rat":"The guidance states a high-risk investment may be suitable in the context of the entire portfolio or when the client's objectives contemplate speculative or risky investments."},{"i":"CFAMC-III-010","t":"A firm's brochure states it \"consistently achieves 25% annual growth,\" when in fact only one fund achieved 25% growth in a single year and the firm's five-year average across all accounts is 5% per year. According to Standard III(D) guidance, this claim is BEST described as:","c":"A","mc":{"s":"A firm's brochure states it \"consistently achieves 25% annual growth,\" when in fact only one fund achieved 25% growth in a single year and the firm's five-year average across all accounts is 5% per year. According to Standard III(D) guidance, this claim is BEST described as:","d":"","o":["Acceptable, since 25% growth genuinely occurred in the most recent year","A violation, because it misrepresents a single fund's one-year result as the firm's expected ongoing performance across accounts","A violation of Standard I(C) Misrepresentation exclusively, since Standard III(D) applies only to GIPS-compliant firms"],"a":2,"cite":"Standard III(D)","rat":"The guidance explains that presenting one portfolio's single-year actual performance as a general, expected firm-wide growth rate misrepresents performance in violation of Standard III(D)."}},{"i":"CFAMC-III-011","t":"An analyst tests a mutual fund selection methodology by retroactively applying it to historical data and then promotes the resulting performance figures to clients without indicating the results are simulated. According to Standard III(D), this is MOST likely a violation because:","c":"A","mc":{"s":"An analyst tests a mutual fund selection methodology by retroactively applying it to historical data and then promotes the resulting performance figures to clients without indicating the results are simulated. According to Standard III(D), this is MOST likely a violation because:","d":"","o":["Simulated performance results may never be shown to clients under any circumstances","The results must be identified as simulated so clients are not misled into believing they reflect actual historical management","Simulated results are permitted only if they outperform an appropriate benchmark"],"a":2,"cite":"Standard III(D)","rat":"The guidance requires full disclosure of the source of performance data, including clearly identifying simulated results; failing to do so is a violation, though simulated results themselves are not prohibited if properly disclosed."}},{"i":"CFAMC-III-012","t":"A performance analyst is instructed not to label whether reported returns are time-weighted or money-weighted, so the firm can present whichever figure looks most favorable each period. According to Standard III(D) guidance, following this instruction would MOST likely result in a violation because:","c":"A","mc":{"s":"A performance analyst is instructed not to label whether reported returns are time-weighted or money-weighted, so the firm can present whichever figure looks most favorable each period. According to Standard III(D) guidance, following this instruction would MOST likely result in a violation because:","d":"","o":["Clients would not receive complete information sufficient to judge the firm's performance","Money-weighted returns are always prohibited from being shown to clients","Standard III(D) requires only that the number reported be numerically accurate, regardless of labeling"],"a":1,"cite":"Standard III(D)","rat":"The guidance concludes that reporting inconsistent, unlabeled return types fails to provide clients with complete information needed to judge the firm's performance."}},{"i":"CFAOX-III-031","t":"Standard III(D) requires members and candidates to make reasonable efforts to ensure that communicated performance information is fair, accurate, and complete.","ox":"O","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard III(D)","rat":"This restates the text of Standard III(D)."},{"i":"CFAOX-III-032","t":"Standard III(D) applies only to members and candidates who manage individual separate accounts, not to those managing pooled funds.","ox":"X","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard III(D)","rat":"The guidance states the requirements are not limited to separate accounts; performance history for pooled funds or other vehicles for which the manager claims responsibility must also be accurate."},{"i":"CFAOX-III-033","t":"If a performance presentation is brief, the member or candidate must make detailed supporting information available to clients and prospects upon request.","ox":"O","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard III(D)","rat":"This is stated directly in the guidance regarding brief presentations."},{"i":"CFAOX-III-034","t":"Compliance with the GIPS standards is described in the guidance as the best method for members and candidates to meet their Standard III(D) obligations when showing performance history.","ox":"O","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard III(D)","rat":"The guidance explicitly recommends GIPS compliance as the best method of meeting Standard III(D) obligations."},{"i":"CFAOX-III-035","t":"A firm that claims compliance with the GIPS standards may still calculate composite returns using a method that does not asset weight portfolio returns, as long as the raw data is accurate.","ox":"X","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard III(D)","rat":"The guidance's example states that claiming GIPS compliance while failing to asset weight portfolio returns, a GIPS requirement, itself violates Standard III(D)."},{"i":"CFAOX-III-036","t":"A portfolio manager who joins a new firm may never reference performance achieved at a prior employer in marketing materials.","ox":"X","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard III(D)","rat":"The guidance states showing past performance from a prior firm is generally not prohibited, as long as appropriate disclosure is made about where the performance occurred and the person's specific role."},{"i":"CFAOX-III-037","t":"Simulated investment performance results may be presented to clients under Standard III(D) as long as they are clearly identified as simulated.","ox":"O","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard III(D)","rat":"The guidance's example states Davis's violation was failing to disclose that results were simulated, implying disclosed simulated results are permissible."},{"i":"CFAOX-III-038","t":"Changing the composition of accounts included in a performance composite over time to selectively improve reported results is consistent with Standard III(D) as long as each individual account's data is accurate.","ox":"X","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard III(D)","rat":"The guidance's example concludes that manipulating which accounts make up a composite to improve results, without proper disclosure, violates Standard III(D)."},{"i":"CFAOX-III-039","t":"Modifying a firm's performance attribution methodology solely to make the firm's stock-selection skill appear stronger, without proper disclosure, fails to meet Standard III(D)'s requirements.","ox":"O","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard III(D)","rat":"The guidance's Purell example states that undisclosed attribution methodology changes made to improve appearance obscure the facts and fail to meet Standard III(D)."},{"i":"CFAOX-III-040","t":"Standard III(D) is satisfied as long as the numeric performance figures reported are technically accurate, regardless of whether clients are told if figures are gross of fees, net of fees, or after tax.","ox":"X","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard III(D)","rat":"The guidance lists disclosing whether performance is gross of fees, net of fees, or after tax as part of providing fair, accurate, and complete information."},{"i":"CFAMC-III-013","t":"An investment officer, aware from an advisory client that the client plans to donate roughly US$50,000 to charity, recommends that a charity she also serves as treasurer solicit that specific client for a gift in that range. This is BEST described as:","c":"A","mc":{"s":"An investment officer, aware from an advisory client that the client plans to donate roughly US$50,000 to charity, recommends that a charity she also serves as treasurer solicit that specific client for a gift in that range. This is BEST described as:","d":"","o":["Acceptable, because the officer's intent to benefit the charity was well-meaning","A violation of Standard III(E), because she disclosed confidential client information for a purpose unrelated to the advisory relationship","Acceptable, because charitable donation plans are not considered confidential financial information"],"a":2,"cite":"Standard III(E)","rat":"The guidance's example concludes that revealing this confidential client information, even for a well-intentioned charitable purpose, violates Standard III(E)."}},{"i":"CFAMC-III-014","t":"According to Standard III(E) guidance, if applicable law requires disclosure of client information in certain circumstances, a member or candidate should MOST appropriately:","c":"A","mc":{"s":"According to Standard III(E) guidance, if applicable law requires disclosure of client information in certain circumstances, a member or candidate should MOST appropriately:","d":"","o":["Refuse disclosure in all cases, since client confidentiality always overrides legal requirements","Comply with the law, since Standard I(A) Knowledge of the Law requires compliance with applicable law","Disclose the information only if the client first consents in writing, regardless of what the law requires"],"a":2,"cite":"Standard III(E)","rat":"The guidance states that when applicable law requires disclosure, members and candidates must comply with the law, consistent with Standard I(A)."}},{"i":"CFAMC-III-015","t":"Standard III(E) is LEAST likely to prevent a member or candidate from:","c":"A","mc":{"s":"Standard III(E) is LEAST likely to prevent a member or candidate from:","d":"","o":["Discussing a former client's confidential account records with an unrelated third party without authorization","Cooperating with a CFA Institute Professional Conduct investigation into the member's own conduct","Disclosing a current client's portfolio holdings to a journalist as a professional courtesy"],"a":2,"cite":"Standard III(E)","rat":"The guidance states Standard III(E) does not prevent cooperation with CFA Institute Professional Conduct investigations, and members must cooperate unless prevented by law; the other two actions involve improper disclosure of confidential client information."}},{"i":"CFAOX-III-041","t":"Standard III(E) requires members and candidates to keep client information confidential unless it concerns illegal client activities, disclosure is required by law, or the client permits disclosure.","ox":"O","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard III(E)","rat":"This restates the three exceptions listed in the text of Standard III(E)."},{"i":"CFAOX-III-042","t":"The duty of confidentiality under Standard III(E) ends automatically as soon as a person is no longer a current client.","ox":"X","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard III(E)","rat":"The guidance states members must continue to maintain confidentiality of client records even after the client relationship has ended."},{"i":"CFAOX-III-043","t":"If applicable law requires a member to maintain confidentiality even where information concerns illegal client activity, the member must comply with the law and not disclose the information.","ox":"O","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard III(E)","rat":"The guidance states that when law requires confidentiality even regarding illegal activity, members must comply with the law rather than disclose."},{"i":"CFAOX-III-044","t":"Standard III(E) prevents members and candidates from cooperating with a CFA Institute Professional Conduct investigation into their own conduct.","ox":"X","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard III(E)","rat":"The guidance explicitly states Standard III(E) does not prevent cooperation with Professional Conduct investigations, and cooperation is generally required unless prevented by law."},{"i":"CFAOX-III-045","t":"Best practice for protecting vulnerable investors under Standard III(E) is to establish a secondary contact with the client's permission at the beginning of the relationship.","ox":"O","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard III(E)","rat":"The guidance recommends establishing a secondary contact, such as a trusted family member or legal adviser, at the start of the client relationship."},{"i":"CFAOX-III-046","t":"Standard III(E) requires members and candidates to become experts in information security technology to protect electronically stored client data.","ox":"X","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard III(E)","rat":"The guidance explicitly states Standard III(E) does not require members to become experts in information security technology, only to understand their employer's relevant policies."},{"i":"CFAOX-III-047","t":"Disclosing a client's confidential building-expansion plans to an unrelated third party who wants the information for an unrelated business decision, without the client's authorization, violates Standard III(E).","ox":"O","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard III(E)","rat":"The guidance's Connor example concludes that disclosing such confidential information obtained within the scope of the advisory relationship to an outside party is prohibited."},{"i":"CFAOX-III-048","t":"A member who suspects a client is being defrauded by a corporate officer should seek the advice of legal counsel to determine the appropriate steps for complying with applicable law.","ox":"O","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard III(E)","rat":"The guidance's Samuel example concludes that consulting legal counsel to determine the appropriate response to suspected illegal activity is the appropriate course of action."},{"i":"CFAOX-III-049","t":"All conversations with a client or outside parties regarding the disclosure of sensitive or confidential information should be fully documented and retained in client files.","ox":"O","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard III(E)","rat":"This is stated directly in the guidance's discussion of vulnerable investors."},{"i":"CFAOX-III-050","t":"A member may disclose a client's confidential information to any fellow employee at the firm, regardless of whether that employee works on the client's account.","ox":"X","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard III(E)","rat":"The compliance practices state members should avoid disclosing client information except to authorized fellow employees who are also working for the client."}],"2":[{"i":"CFAMC-II-001","t":"An analyst combines publicly available information with nonmaterial nonpublic details gathered from customers, suppliers, and competitors to reach a conclusion that, if disclosed directly by the company, would have been material. Under the guidance to Standard II(A), the analyst's use of this conclusion in a recommendation is BEST described as:","c":"A","mc":{"s":"An analyst combines publicly available information with nonmaterial nonpublic details gathered from customers, suppliers, and competitors to reach a conclusion that, if disclosed directly by the company, would have been material. Under the guidance to Standard II(A), the analyst's use of this conclusion in a recommendation is BEST described as:","d":"","o":["A violation, because the resulting conclusion is itself material information","Permitted under the mosaic theory, because it was derived from public and nonmaterial nonpublic information","A violation, unless the analyst first discloses the conclusion publicly before using it"],"a":2,"cite":"Standard II(A)","rat":"Under the mosaic theory described in the guidance, an analyst may act on conclusions derived from public and nonmaterial nonpublic information even if the same conclusion would have been material inside information had it come directly from the company."}},{"i":"CFAMC-II-002","t":"A well-known analyst issues a report with conclusions that move the market once published, based entirely on the analyst's own interpretation of publicly available information. According to Standard II(A) guidance, is the analyst required to make the underlying work public before other investors can access it?","c":"A","mc":{"s":"A well-known analyst issues a report with conclusions that move the market once published, based entirely on the analyst's own interpretation of publicly available information. According to Standard II(A) guidance, is the analyst required to make the underlying work public before other investors can access it?","d":"","o":["Yes, because market-moving conclusions must always be released to all investors simultaneously","No, other investors may either do the work themselves or become the analyst's client to access the expertise","Yes, but only if the analyst is a CFA charterholder"],"a":2,"cite":"Standard II(A)","rat":"The guidance clarifies that simply because the public would find an analyst's conclusions material does not require the analyst to make the underlying work public; non-clients may replicate the work or become clients."}},{"i":"CFAMC-II-003","t":"A member obtains material nonpublic information about an issuer and is unable to convince the company to disseminate it publicly. According to the compliance practices under Standard II(A), the member should MOST appropriately:","c":"A","mc":{"s":"A member obtains material nonpublic information about an issuer and is unable to convince the company to disseminate it publicly. According to the compliance practices under Standard II(A), the member should MOST appropriately:","d":"","o":["Trade on the information for the firm's proprietary account only, since client accounts are protected","Communicate the information only to designated supervisory and compliance personnel and refrain from taking investment action based on it","Share the information with select long-term clients while keeping other clients uninformed"],"a":2,"cite":"Standard II(A)","rat":"The compliance practices guidance requires that, if public dissemination cannot be achieved, the information be communicated only to designated supervisory and compliance personnel, with no investment action taken on it."}},{"i":"CFAOX-II-001","t":"Standard II(A) prohibits members and candidates who possess material nonpublic information from acting on it or causing others to act on it.","ox":"O","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard II(A)","rat":"This restates the text of Standard II(A)."},{"i":"CFAOX-II-002","t":"Information is considered material only if it relates to derivatives trading; equity and bond trades are outside the scope of Standard II(A).","ox":"X","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard II(A)","rat":"The prohibition applies broadly to securities, bonds, derivatives, mutual funds, and other alternative investments, not just derivatives."},{"i":"CFAOX-II-003","t":"The reliability of the source of information is a relevant factor in determining whether information is material under Standard II(A).","ox":"O","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard II(A)","rat":"The guidance states that the less reliable the source, the less likely the information is to be considered material."},{"i":"CFAOX-II-004","t":"A disclosure made to a room full of analysts at a conference call is automatically considered public information under Standard II(A).","ox":"X","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard II(A)","rat":"The guidance states a disclosure to a room of analysts does not necessarily make information public; it remains nonpublic until disseminated to investors generally."},{"i":"CFAOX-II-005","t":"Under the mosaic theory, an analyst may use conclusions derived from public and nonmaterial nonpublic information even if the same conclusion would have been material had it come directly from the company.","ox":"O","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard II(A)","rat":"The guidance explicitly describes this as the mosaic theory and states analysts may act on such conclusions without violating Standard II(A)."},{"i":"CFAOX-II-006","t":"A member or candidate who obtains insider information legitimately for a specific due diligence purpose, such as a merger engagement, violates Standard II(A) merely by using it for that purpose.","ox":"X","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard II(A)","rat":"The guidance states using insider information for the specific legitimate due diligence purpose for which it was provided does not violate Standard II(A); using it for other purposes, such as trading, would."},{"i":"CFAOX-II-007","t":"If a member cannot convince a company to publicly disseminate material nonpublic information it possesses, the member should communicate it only to designated supervisory and compliance personnel and must not take investment action on it.","ox":"O","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard II(A)","rat":"This is a compliance practice stated directly in the guidance for handling undisseminated material nonpublic information."},{"i":"CFAOX-II-008","t":"Members and candidates are permitted to act on material nonpublic information received from an outside industry expert as long as they paid the expert for the insight.","ox":"X","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard II(A)","rat":"The guidance states members are prohibited from taking investment action on material nonpublic information from an expert until it becomes publicly known, regardless of compensation paid."},{"i":"CFAOX-II-009","t":"An effective firewall requires that an employee, such as a research analyst who assists an investment banking deal, remain on only one side of the information barrier at a time.","ox":"O","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard II(A)","rat":"The guidance states an employee should be on only one side of the firewall at any time, and an analyst assisting on a banking deal must remain there until the information is publicly disclosed."},{"i":"CFAOX-II-010","t":"Information available only to members of a restricted social media group is automatically public information under Standard II(A) once it is posted online.","ox":"X","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard II(A)","rat":"The guidance notes such membership-limited content may not be public, and members should verify the information can also be accessed through a source available to the public before using it."},{"i":"CFAMC-II-004","t":"An investor who holds a large, illiquid position splits his holdings across multiple accounts under different names and trades between them to create the appearance of higher trading volume and rising prices before selling his position. This is BEST described as a violation of Standard II(B) through:","c":"A","mc":{"s":"An investor who holds a large, illiquid position splits his holdings across multiple accounts under different names and trades between them to create the appearance of higher trading volume and rising prices before selling his position. This is BEST described as a violation of Standard II(B) through:","d":"","o":["Information-based manipulation only","Transaction-based manipulation that artificially distorts trading volume and price","No violation, because he only traded his own beneficially owned securities"],"a":2,"cite":"Standard II(B)","rat":"Trading among accounts to create a false appearance of activity or price movement is transaction-based manipulation prohibited by Standard II(B), regardless of whether the trader owns all the securities involved."}},{"i":"CFAMC-II-005","t":"According to the guidance under Standard II(B), which of the following is LEAST likely to be treated as market manipulation?","c":"A","mc":{"s":"According to the guidance under Standard II(B), which of the following is LEAST likely to be treated as market manipulation?","d":"","o":["Disseminating overly optimistic, misleading projections about a security to drive up its price before selling the position","Placing orders intended to change the bid or offer price and then canceling them before execution","Engaging in a legitimate trading strategy based on a genuine, reasoned view of market inefficiency, even if it appears unusual in an illiquid market"],"a":3,"cite":"Standard II(B)","rat":"The guidance states Standard II(B) is not intended to preclude legitimate trading strategies based on perceived market inefficiencies, even though such trading may appear abusive in illiquid or volatile markets; intent is the key factor."}},{"i":"CFAMC-II-006","t":"An analyst deliberately exaggerates her earnings estimate for a company, well beyond her own genuine analysis, and tells clients the estimate to try to pressure the company into revising its guidance and to generate a quick trading gain. This conduct is BEST characterized as violating Standard II(B) because:","c":"A","mc":{"s":"An analyst deliberately exaggerates her earnings estimate for a company, well beyond her own genuine analysis, and tells clients the estimate to try to pressure the company into revising its guidance and to generate a quick trading gain. This conduct is BEST characterized as violating Standard II(B) because:","d":"","o":["Analysts are never permitted to publish earnings estimates that differ from management's guidance","She disseminated a misleading projection with intent to create artificial price movement rather than presenting a genuinely reasoned range of outcomes","She contacted the company's CFO to seek confirmation of her model updates before publishing"],"a":2,"cite":"Standard II(B)","rat":"The guidance distinguishes an honestly reasoned range of estimates with disclosed assumptions from exaggerating a projection to manufacture a quick price move, the latter being a violation."}},{"i":"CFAOX-II-011","t":"Standard II(B) prohibits practices that distort prices or artificially inflate trading volume with the intent to mislead market participants.","ox":"O","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard II(B)","rat":"This restates the text of Standard II(B)."},{"i":"CFAOX-II-012","t":"Standard II(B) covers only transaction-based manipulation; spreading false rumors to induce trading is outside its scope.","ox":"X","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard II(B)","rat":"The guidance identifies two categories: information-based manipulation, including spreading false rumors, and transaction-based manipulation."},{"i":"CFAOX-II-013","t":"A \"pump and dump\" scheme, where a holder spreads misleading positive information to inflate a price before selling, is an example of information-based manipulation under Standard II(B).","ox":"O","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard II(B)","rat":"The guidance explicitly describes pumping up a price with misleading information and then dumping the position as a violation."},{"i":"CFAOX-II-014","t":"Standard II(B) is intended to preclude any legitimate trading strategy that exploits a perceived market inefficiency, even absent any intent to mislead.","ox":"X","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard II(B)","rat":"The guidance states Standard II(B) is not intended to preclude legitimate trading strategies based on perceived market inefficiencies; intent to deceive is the determining factor."},{"i":"CFAOX-II-015","t":"Securing a controlling or dominant position in a financial instrument in order to exploit and manipulate the price of a related derivative can constitute transaction-based manipulation.","ox":"O","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard II(B)","rat":"This is listed directly as an example of transaction-based manipulation in the guidance."},{"i":"CFAOX-II-016","t":"Orders that are entered and then canceled before execution, intended to change the bid or offer price, are listed in the guidance as a possible indicator of market manipulation.","ox":"O","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard II(B)","rat":"The guidance's nonexhaustive list of manipulation indicators includes orders intended to change bid or offer prices that are canceled before execution."},{"i":"CFAOX-II-017","t":"Coordinated trading action by two or more traders in a market with a small number of participants is listed as a possible indicator of market manipulation.","ox":"O","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard II(B)","rat":"This is included in the guidance's list of indicators that may signal market manipulation."},{"i":"CFAOX-II-018","t":"An analyst who deliberately exaggerates an earnings estimate beyond her genuine analysis, in order to pressure a company and create a quick trading gain for clients, has complied with Standard II(B) as long as the direction of her estimate later proves correct.","ox":"X","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard II(B)","rat":"The guidance states this conduct violates Standard II(B) because of the intent to manufacture artificial price movement, regardless of whether the estimate later proves directionally accurate."},{"i":"CFAOX-II-019","t":"Market manipulation is considered more likely to reduce investor confidence and raise risk premiums, potentially harming a country's broader economic growth.","ox":"O","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard II(B)","rat":"The guidance connects market manipulation to reduced trust, higher risk premiums, reduced investor participation, and negative effects on a market's economic health."},{"i":"CFAOX-II-020","t":"Because mature financial markets are described as less susceptible to manipulation than emerging markets, cross-border investors in mature markets face no exposure to manipulative practices.","ox":"X","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard II(B)","rat":"The guidance notes manipulation may be less likely in mature markets but states cross-border investing still exposes all global investors to the potential for such practices."}],"4":[{"i":"CFAMC-IV-001","t":"Before resigning, a portfolio manager persuades several of his current employer's large accounts and prospective clients he had previously presented to on the firm's behalf to move to his new employer. This is BEST described as:","c":"A","mc":{"s":"Before resigning, a portfolio manager persuades several of his current employer's large accounts and prospective clients he had previously presented to on the firm's behalf to move to his new employer. This is BEST described as:","d":"","o":["Acceptable, since he is free to build his new employer's client base as soon as he receives a job offer","A violation of Standard IV(A), because he solicited his current employer's clients and prospects while still employed there","Acceptable, as long as he waits until after he formally submits his letter of resignation"],"a":2,"cite":"Standard IV(A)","rat":"The guidance's Magee example concludes that soliciting an employer's current and prospective clients while still employed there violates the duty of loyalty under Standard IV(A), and the duty continues through the notice period."}},{"i":"CFAMC-IV-002","t":"A departing senior portfolio manager plans to copy and take a client list, account statements, and proprietary asset-allocation models he developed while employed, without his former employer's consent. According to Standard IV(A) guidance, this is MOST likely:","c":"A","mc":{"s":"A departing senior portfolio manager plans to copy and take a client list, account statements, and proprietary asset-allocation models he developed while employed, without his former employer's consent. According to Standard IV(A) guidance, this is MOST likely:","d":"","o":["Acceptable, because he personally developed the models and prepared much of the material himself","A violation, because employer records may not be taken upon departure without the employer's consent, even those the employee prepared","Acceptable only for the computer models, since client lists but not internal models are considered employer property"],"a":2,"cite":"Standard IV(A)","rat":"The guidance states that taking any employer records without consent, even records the employee personally prepared, violates Standard IV(A)."}},{"i":"CFAMC-IV-003","t":"According to the guidance under Standard IV(A), a member or candidate who plans to start an independent business for compensation while still employed must:","c":"A","mc":{"s":"According to the guidance under Standard IV(A), a member or candidate who plans to start an independent business for compensation while still employed must:","d":"","o":["Notify the employer of the services, duration, and compensation involved, and not render services until the employer consents to all terms","Keep the plans confidential from the employer until the business is fully operational, to avoid unnecessary conflict","Obtain approval only if the independent business directly competes with the employer's core services"],"a":1,"cite":"Standard IV(A)","rat":"The guidance requires notifying the employer of the type, duration, and compensation of independent services and refraining from rendering such services until the employer consents to all the arrangement's terms."}},{"i":"CFAOX-IV-001","t":"Standard IV(A) requires members and candidates to act for the benefit of their employer and not deprive the employer of their skills, confidential information, or otherwise cause harm to the firm.","ox":"O","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard IV(A)","rat":"This restates the text of Standard IV(A)."},{"i":"CFAOX-IV-002","t":"Standard IV(A) is a blanket requirement that employer interests always come before a member's personal and family obligations.","ox":"X","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard IV(A)","rat":"The guidance explicitly states this standard does not require subordinating important personal and family obligations to work in all matters."},{"i":"CFAOX-IV-003","t":"A member may not offer a service that competes with a service offered by the employer without the employer's consent.","ox":"O","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard IV(A)","rat":"The guidance states members are prohibited from providing a service offered by their employer without the employer's consent."},{"i":"CFAOX-IV-004","t":"Members and candidates may solicit their employer's clients for a new employer as soon as they have accepted a job offer, even before giving notice.","ox":"X","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard IV(A)","rat":"The guidance requires continued loyalty until the employment relationship ends, prohibiting solicitation of clients or promotion of a new employer prior to cessation of employment."},{"i":"CFAOX-IV-005","t":"After giving notice of resignation, members and candidates may provide the name of their new employer to clients but must not provide new-employer contact information or describe the new firm's services without the current employer's permission.","ox":"O","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard IV(A)","rat":"This is stated directly in the guidance on leaving an employer."},{"i":"CFAOX-IV-006","t":"Once employment with a former firm has ended, a member is prohibited from ever contacting that firm's former clients using publicly available information.","ox":"X","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard IV(A)","rat":"The guidance states departed members may contact former clients using public information, as long as the contact information did not come from former-employer records and no applicable agreement prohibits it."},{"i":"CFAOX-IV-007","t":"Skills and experience a member gained while employed at a firm become confidential information that cannot be used once the member leaves that firm.","ox":"X","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard IV(A)","rat":"The guidance states skills and experience gained at one employer are not confidential and may be used at a subsequent employer."},{"i":"CFAOX-IV-008","t":"A member may take copies of client account statements and firm marketing materials to a new employer without consent, as long as the member personally prepared those materials.","ox":"X","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard IV(A)","rat":"The guidance states taking any employer records, even those prepared by the member, without consent violates Standard IV(A)."},{"i":"CFAOX-IV-009","t":"Under the whistle-blowing guidance, actions that would normally violate the duty to an employer, such as copying records to preserve evidence, may be justified when clearly aimed at protecting clients or market integrity rather than personal gain.","ox":"O","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard IV(A)","rat":"The guidance describes this exception for whistle-blowing situations directed at protecting clients or capital market integrity."},{"i":"CFAOX-IV-010","t":"Standard IV(A) applies only to members and candidates who are formal employees; it has no bearing on independent contractor relationships.","ox":"X","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard IV(A)","rat":"The guidance addresses independent contractor relationships directly, stating duties are governed by the oral or written agreement and that determining employee versus contractor status affects the standard's application."},{"i":"CFAMC-IV-004","t":"A client offers her portfolio manager an all-expenses-paid trip to Monaco if her portfolio achieves at least a 15% return in a given year. The manager accepts without informing his employer. This is BEST described as:","c":"A","mc":{"s":"A client offers her portfolio manager an all-expenses-paid trip to Monaco if her portfolio achieves at least a 15% return in a given year. The manager accepts without informing his employer. This is BEST described as:","d":"","o":["Acceptable, since the arrangement is between the manager and his own client","A violation of Standard IV(B), because the manager failed to obtain his employer's consent to this contingent supplemental compensation","Acceptable, as long as the manager's other client accounts do not decline in performance"],"a":2,"cite":"Standard IV(B)","rat":"The guidance concludes that accepting a client-contingent supplemental benefit without informing the employer violates Standard IV(B), because such an arrangement could create partiality toward that client's account."}},{"i":"CFAMC-IV-005","t":"A portfolio manager sits on a company's board of directors and receives nonmonetary membership benefits, then recommends that company's stock for client accounts without disclosing the board arrangement to his employer, reasoning that no cash compensation was involved. According to Standard IV(B) guidance, this reasoning is:","c":"A","mc":{"s":"A portfolio manager sits on a company's board of directors and receives nonmonetary membership benefits, then recommends that company's stock for client accounts without disclosing the board arrangement to his employer, reasoning that no cash compensation was involved. According to Standard IV(B) guidance, this reasoning is:","d":"","o":["Correct, because Standard IV(B) applies only to monetary compensation arrangements","Incorrect, because nonmonetary benefits can create the same type of conflict of interest as monetary compensation and must be disclosed","Correct, because board service is outside the scope of Standard IV(B) entirely"],"a":2,"cite":"Standard IV(B)","rat":"The guidance states nonmonetary compensation, such as board membership benefits, may create a conflict of interest in the same manner as monetary payment and must be disclosed to the employer."}},{"i":"CFAMC-IV-006","t":"An analyst is invited by a company's CEO to visit its headquarters after publishing a favorable research report. He obtains approval before accepting the meeting, declines the company's offered travel arrangements, and discloses to his employer a dinner he attended with company officials. According to Standard IV(B) guidance, the analyst's conduct is BEST described as:","c":"A","mc":{"s":"An analyst is invited by a company's CEO to visit its headquarters after publishing a favorable research report. He obtains approval before accepting the meeting, declines the company's offered travel arrangements, and discloses to his employer a dinner he attended with company officials. According to Standard IV(B) guidance, the analyst's conduct is BEST described as:","d":"","o":["A violation, because any interaction with a covered company's CEO following a favorable report creates an unavoidable conflict","Consistent with Standard IV(B), because he obtained prior approval, limited the benefits accepted, and disclosed what occurred","A violation, because he should have declined the meeting altogether to avoid any appearance of conflict"],"a":2,"cite":"Standard IV(B)","rat":"The guidance concludes that seeking approval in advance, declining offered travel, and disclosing the dinner afterward did not violate Standard IV(B), since it allowed the employer to assess any impact on future recommendations."}},{"i":"CFAOX-IV-011","t":"Standard IV(B) requires members and candidates to obtain written consent from all relevant parties before accepting gifts, benefits, or compensation that competes with or might create a conflict with their employer's interest.","ox":"O","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard IV(B)","rat":"This restates the text of Standard IV(B)."},{"i":"CFAOX-IV-012","t":"Standard IV(B) applies only to direct monetary compensation from clients; indirect nonmonetary benefits from third parties are outside its scope.","ox":"X","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard IV(B)","rat":"The guidance states compensation and benefits include both direct compensation and indirect compensation or benefits from third parties, including nonmonetary benefits."},{"i":"CFAOX-IV-013","t":"A client-contingent bonus arrangement, such as a paid vacation tied to portfolio performance, must be disclosed to the employer because it could create partiality toward that client's account.","ox":"O","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard IV(B)","rat":"The guidance's Whitman example concludes such contingent arrangements must be disclosed because of the risk of partiality toward the paying client."},{"i":"CFAOX-IV-014","t":"Nonmonetary compensation, such as membership benefits received for serving on a company's board, does not need to be disclosed under Standard IV(B) because no cash changes hands.","ox":"X","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard IV(B)","rat":"The guidance states nonmonetary compensation can create the same type of conflict of interest as monetary compensation and must be disclosed."},{"i":"CFAOX-IV-015","t":"Written consent under Standard IV(B) can include any documentable form of communication, such as an email that can be retrieved and documented.","ox":"O","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard IV(B)","rat":"The guidance explicitly defines written consent to include documentable communications such as email."},{"i":"CFAOX-IV-016","t":"Disclosure under Standard IV(B) should include the nature, approximate amount, and duration of any additional compensation arrangement.","ox":"O","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard IV(B)","rat":"The compliance practices guidance lists these elements as required parts of the disclosure to the employer."},{"i":"CFAOX-IV-017","t":"An analyst who obtains prior approval, declines offered travel, and later discloses a dinner with a covered company's executives has necessarily violated Standard IV(B) simply by meeting with the company.","ox":"X","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard IV(B)","rat":"The guidance's Hollis example concludes that seeking approval, limiting accepted benefits, and disclosing what occurred did not violate Standard IV(B)."},{"i":"CFAOX-IV-018","t":"Members and candidates working part-time or on contract for multiple employers should negotiate and address, during the hiring process, the parameters around providing services to other, potentially competing employers.","ox":"O","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard IV(B)","rat":"This is stated directly in the guidance regarding part-time or contract arrangements."},{"i":"CFAOX-IV-019","t":"Standard IV(B) requires disclosure to be made to the employer generally, without needing to route it through a supervisor or compliance officer.","ox":"X","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard IV(B)","rat":"The compliance practices specify disclosure should be made to the employer through the member's supervisor or compliance officer."},{"i":"CFAOX-IV-020","t":"The party offering additional compensation to a member should acknowledge and confirm the details disclosed to the employer.","ox":"O","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard IV(B)","rat":"This is stated directly in the compliance practices guidance for Standard IV(B)."},{"i":"CFAMC-IV-007","t":"A supervisor has adopted and enforced reasonable, well-designed compliance procedures, yet an employee still commits a violation that the procedures did not catch. According to Standard IV(C) guidance, the supervisor:","c":"A","mc":{"s":"A supervisor has adopted and enforced reasonable, well-designed compliance procedures, yet an employee still commits a violation that the procedures did not catch. According to Standard IV(C) guidance, the supervisor:","d":"","o":["Has automatically violated Standard IV(C), because any undetected violation proves the supervisor failed in the duty of supervision","May not be in violation of Standard IV(C), since reasonable, properly implemented procedures were in place, though the occurrence may signal the procedures need review","Has violated Standard IV(C) only if the employee is also a CFA Institute member or candidate"],"a":2,"cite":"Standard IV(C)","rat":"The guidance states a supervisor with reasonable, properly instituted compliance procedures may not violate Standard IV(C) for an undetected violation, though repeated violations may indicate inadequate procedures."}},{"i":"CFAMC-IV-008","t":"Upon learning that an employee may have violated the law, a supervisor merely accepts the employee's assurance that the conduct will not happen again and reports the matter to compliance, without further investigation or restriction on the employee's activities. According to Standard IV(C) guidance, this response is:","c":"A","mc":{"s":"Upon learning that an employee may have violated the law, a supervisor merely accepts the employee's assurance that the conduct will not happen again and reports the matter to compliance, without further investigation or restriction on the employee's activities. According to Standard IV(C) guidance, this response is:","d":"","o":["Sufficient, because reporting to compliance and obtaining the employee's assurance satisfies the supervisor's duty","Insufficient, because the supervisor must promptly investigate the extent of the wrongdoing and take steps, such as increased monitoring or limits, pending the outcome","Sufficient, as long as the employee is a first-time offender"],"a":2,"cite":"Standard IV(C)","rat":"The guidance explicitly states that relying on an employee's assurances or merely reporting the matter is not enough; the supervisor must promptly assess the wrongdoing and limit or monitor the employee pending the investigation's outcome."}},{"i":"CFAMC-IV-009","t":"According to the guidance under Standard IV(C), a firm's standalone code of ethics is MOST effectively written when it:","c":"A","mc":{"s":"According to the guidance under Standard IV(C), a firm's standalone code of ethics is MOST effectively written when it:","d":"","o":["Combines detailed compliance procedures and legal boilerplate with general ethical principles in a single comprehensive document","States fundamental, principle-based ethical concepts in plain, accessible language, separate from detailed compliance procedures","Is drafted exclusively by outside legal counsel using formal regulatory terminology to ensure enforceability"],"a":2,"cite":"Standard IV(C)","rat":"The guidance states codes of ethics should be principle-based, written in plain language, and kept separate from detailed compliance procedures, which are implemented separately by supervisors."}},{"i":"CFAOX-IV-021","t":"Standard IV(C) requires members and candidates to make reasonable efforts to ensure that anyone subject to their supervision or authority complies with applicable laws, rules, regulations, and the Code and Standards.","ox":"O","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard IV(C)","rat":"This restates the text of Standard IV(C)."},{"i":"CFAOX-IV-022","t":"Supervisory responsibility under Standard IV(C) applies only when the supervised employees are themselves CFA Institute members, charterholders, or candidates.","ox":"X","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard IV(C)","rat":"The guidance states supervisory responsibility applies to any employees under the member's or candidate's control or influence, regardless of the employees' CFA Institute status."},{"i":"CFAOX-IV-023","t":"A member or candidate with supervisory responsibility but no authority to change firm-wide policies has no obligation to work toward improving inadequate compliance systems.","ox":"X","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard IV(C)","rat":"The guidance states such members should still work with their own superiors and within the firm structure to develop and implement effective compliance tools."},{"i":"CFAOX-IV-024","t":"If a firm's compliance system is so inadequate that a member cannot discharge supervisory responsibilities, the member should decline to accept supervisory responsibility until reasonable procedures are adopted.","ox":"O","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard IV(C)","rat":"This is stated directly in the guidance regarding inadequate compliance systems."},{"i":"CFAOX-IV-025","t":"Once a supervisor learns of a possible violation, accepting the employee's own assurance that it will not reoccur, combined with reporting to compliance, fully satisfies the supervisor's obligations under Standard IV(C).","ox":"X","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard IV(C)","rat":"The guidance states this is not enough; the supervisor must promptly investigate and take steps such as increased monitoring or limiting the employee's activities pending the investigation."},{"i":"CFAOX-IV-026","t":"A supervisor who has established and enforced reasonable compliance procedures may not be in violation of Standard IV(C) simply because an undetected violation still occurred.","ox":"O","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard IV(C)","rat":"The guidance states this directly under \"Supervision Includes Detection.\""},{"i":"CFAOX-IV-027","t":"Standalone codes of ethics are most effective when they are filled with detailed compliance procedures and legal terminology alongside the ethical principles.","ox":"X","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard IV(C)","rat":"The guidance states codes of ethics should be unencumbered by detailed procedures or legal boilerplate and should instead be plain-language, principle-based documents."},{"i":"CFAOX-IV-028","t":"Adequate compliance procedures should designate a compliance officer with clearly defined authority, responsibility, and the resources needed to investigate potential violations.","ox":"O","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard IV(C)","rat":"This is listed directly among the features of adequate compliance procedures in the guidance."},{"i":"CFAOX-IV-029","t":"Establishing incentive structures that reward ethical behavior, not just business results, is described in the guidance as a method to encourage compliance under Standard IV(C).","ox":"O","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard IV(C)","rat":"The guidance recommends establishing monetary or other incentives that reward ethical behavior alongside business goals."},{"i":"CFAOX-IV-030","t":"Compliance procedures need only be designed after violations have already occurred, since they cannot realistically anticipate misconduct in advance.","ox":"X","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard IV(C)","rat":"The guidance states compliance procedures must be in place prior to any violation and should be designed to anticipate the activities most likely to result in misconduct."}],"1":[{"i":"CFAMC-I-001","t":"According to Standard I(A), when applicable law and the Code and Standards impose different requirements on a member's conduct, the member must most appropriately:","c":"A","mc":{"s":"According to Standard I(A), when applicable law and the Code and Standards impose different requirements on a member's conduct, the member must most appropriately:","d":"","o":["Always follow applicable law regardless of which is stricter","Always follow the Code and Standards regardless of which is stricter","Follow whichever of the two imposes the stricter requirement"],"a":3,"cite":"Standard I(A)","rat":"Standard I(A) requires members to comply with the more strict of applicable law or the Code and Standards when the two differ."}},{"i":"CFAMC-I-002","t":"Scherzer, a portfolio manager, occasionally assists the CFO's team with the firm's regulatory financial audit but is not the person responsible for the internal audit team. Per the guidance to Standard I(A), which statement is BEST?","c":"A","mc":{"s":"Scherzer, a portfolio manager, occasionally assists the CFO's team with the firm's regulatory financial audit but is not the person responsible for the internal audit team. Per the guidance to Standard I(A), which statement is BEST?","d":"","o":["Standard I(A) requires every employee, regardless of role, to have detailed knowledge of every regulation affecting the firm","Standard I(A) does not require Scherzer, whose primary responsibility is portfolio management, to have detailed knowledge of the audit regulations","Scherzer automatically violates Standard I(A) any time he assists with a task outside his primary role"],"a":2,"cite":"Standard I(A)","rat":"The guidance clarifies that members need detailed knowledge only of laws directly related to their own professional responsibilities, not every regulation touching the firm."}},{"i":"CFAMC-I-003","t":"A member discovers that her firm's promotional material overstates historical performance and raises the issue with the person responsible, without success. According to the dissociation guidance under Standard I(A), the member should NEXT most appropriately:","c":"A","mc":{"s":"A member discovers that her firm's promotional material overstates historical performance and raises the issue with the person responsible, without success. According to the dissociation guidance under Standard I(A), the member should NEXT most appropriately:","d":"","o":["Continue using the material since she did not calculate the numbers herself","Bring the situation to her supervisor or compliance department before taking further steps to dissociate","Immediately notify the government securities regulator, since this is required by Standard I(A)"],"a":2,"cite":"Standard I(A)","rat":"The guidance describes an intermediate step of escalating to a supervisor or compliance department before further dissociation is required; reporting to a regulator is not compelled unless mandated by law."}},{"i":"CFAOX-I-001","t":"Standard I(A) requires members and candidates to comply with the stricter of applicable law and the Code and Standards when the two conflict.","ox":"O","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard I(A)","rat":"When applicable law and the Code and Standards differ, the member must follow whichever imposes the greater restriction or duty."},{"i":"CFAOX-I-002","t":"Standard I(A) requires members and candidates to comply with whichever of applicable law or the Code and Standards is less restrictive.","ox":"X","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard I(A)","rat":"The standard requires the stricter of the two, not the less restrictive one."},{"i":"CFAOX-I-003","t":"A member or candidate who has reasonable grounds to believe a client's activity is ongoing and illegal must dissociate from the activity if raising it directly does not stop it.","ox":"O","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard I(A)","rat":"The guidance describes dissociation, including escalation to a supervisor or compliance department, as the required response to ongoing illegal or unethical activity."},{"i":"CFAOX-I-004","t":"Standard I(A) obligates members and candidates to report every suspected violation of applicable law directly to the relevant government regulator.","ox":"X","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard I(A)","rat":"The Code and Standards encourage but do not compel reporting to regulators unless disclosure is mandatory under applicable law."},{"i":"CFAOX-I-005","t":"Standard I(A) does not require members and candidates to become experts in every law that could potentially apply to their professional activities.","ox":"O","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard I(A)","rat":"The guidance states members need not be experts in compliance or have detailed knowledge of all potentially applicable laws, only those directly related to their responsibilities."},{"i":"CFAOX-I-006","t":"CFA candidates who are not CFA Institute members are bound by the Code and Standards and the Candidate Agreement but not by the Membership Agreement.","ox":"O","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard I(A)","rat":"The Membership Agreement applies to members; candidates instead abide by the Candidate Agreement, Candidate Responsibility Statement, and Candidate Pledge."},{"i":"CFAOX-I-007","t":"A member who relies on legal counsel's opinion that a regulator would find it hard to prove wrongdoing is thereby relieved of the duty to comply with the law.","ox":"X","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard I(A)","rat":"The guidance states that reliance on legal advice does not absolve a member or candidate from the requirement to comply with the law."},{"i":"CFAOX-I-008","t":"Dissociation from a colleague's or employer's violation may, in extreme cases, require a member or candidate to leave their employment.","ox":"O","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard I(A)","rat":"The guidance explicitly notes that dissociation may in extreme cases require leaving one's employment."},{"i":"CFAOX-I-009","t":"When discovering a colleague's ethical violation, Standard I(A) guidance states the appropriate first step is to resign from the firm immediately.","ox":"X","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard I(A)","rat":"The first step is to attempt to stop the behavior through the employer's supervisor or compliance department, not immediate resignation."},{"i":"CFAOX-I-010","t":"Members and candidates involved in creating or maintaining investment products must understand and comply with applicable laws and regulations in all relevant jurisdictions where those products are sold or originated.","ox":"O","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard I(A)","rat":"The guidance on investment products and applicable laws requires this due diligence for cross-border and multi-jurisdictional activity."},{"i":"CFAMC-I-004","t":"Grant directs a large amount of commission business to a brokerage house, which in appreciation gives him World Cup tickets, resort nights, meals, and limousine transportation. According to Standard I(B), Grant's acceptance of these benefits is BEST described as:","c":"A","mc":{"s":"Grant directs a large amount of commission business to a brokerage house, which in appreciation gives him World Cup tickets, resort nights, meals, and limousine transportation. According to Standard I(B), Grant's acceptance of these benefits is BEST described as:","d":"","o":["Acceptable, because gifts from brokers who receive commission business are always exempt from Standard I(B)","A violation, because the substantial gifts could reasonably be expected to affect his independence and objectivity","Acceptable, as long as Grant privately intends not to let the gifts affect his future order flow"],"a":2,"cite":"Standard I(B)","rat":"The guidance treats such substantial, unsolicited gifts from a party benefiting from the member's business as a violation because they could reasonably be expected to compromise independence and objectivity."}},{"i":"CFAMC-I-005","t":"An independent analyst is hired by an investor relations firm to write a research report on a company, with payment structured as a flat fee plus a bonus if the report attracts new investors. According to Standard I(B), this arrangement is LEAST likely to be acceptable because:","c":"A","mc":{"s":"An independent analyst is hired by an investor relations firm to write a research report on a company, with payment structured as a flat fee plus a bonus if the report attracts new investors. According to Standard I(B), this arrangement is LEAST likely to be acceptable because:","d":"","o":["Issuer-paid research is prohibited outright under Standard I(B)","The bonus tied to attracting investors gives an incentive to write a favorable report regardless of the facts","Analysts are never permitted to accept any compensation from parties other than their employer"],"a":2,"cite":"Standard I(B)","rat":"The guidance explains that compensation linked to a report's conclusions or its success in attracting investors creates an incentive to bias the analysis; a flat fee not tied to conclusions is the acceptable approach."}},{"i":"CFAMC-I-006","t":"A client whose portfolio has consistently beaten its benchmark gives the manager two tickets to a major sporting event as a reward. According to Standard I(B) guidance, the manager should MOST appropriately:","c":"A","mc":{"s":"A client whose portfolio has consistently beaten its benchmark gives the manager two tickets to a major sporting event as a reward. According to Standard I(B) guidance, the manager should MOST appropriately:","d":"","o":["Decline the gift outright, since accepting any gift from a client always violates Standard I(B)","Accept the gift without any further action, since gifts from clients are never a concern under Standard I(B)","Accept the gift and disclose it to the employer so it can be monitored for effects on objectivity"],"a":3,"cite":"Standard I(B)","rat":"Gifts from clients may be accepted as they are deemed less likely to impair objectivity than gifts from other parties, but disclosure to the employer is required so the relationship can be monitored."}},{"i":"CFAOX-I-011","t":"Standard I(B) prohibits members and candidates from offering, soliciting, or accepting any gift, benefit, or consideration that could reasonably be expected to compromise independence and objectivity.","ox":"O","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard I(B)","rat":"This is the core text of Standard I(B)."},{"i":"CFAOX-I-012","t":"Standard I(B) permits members and candidates to accept lavish entertainment from a broker as long as they privately intend to remain unbiased.","ox":"X","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard I(B)","rat":"Members must reject gifts or entertainment that could reasonably be expected to threaten independence and objectivity, regardless of private intentions; only modest gifts and entertainment are acceptable."},{"i":"CFAOX-I-013","t":"A gift received from a client, unlike a gift from an outside party seeking influence, may be accepted as long as it is disclosed to the employer.","ox":"O","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard I(B)","rat":"Gifts from clients are viewed as potential supplementary compensation and are deemed less likely to impair objectivity, but disclosure to the employer is required."},{"i":"CFAOX-I-014","t":"Best practice under Standard I(B) is for members and candidates to pay for their own commercial transportation to issuer site visits rather than accept paid travel from the company being researched.","ox":"O","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard I(B)","rat":"The travel funding guidance states members should use commercial transportation at their own or their firm's expense rather than accept an outside company's paid travel."},{"i":"CFAOX-I-015","t":"Members and candidates acting as independent, issuer-paid research analysts should negotiate compensation tied to the conclusions of their report so that positive outcomes are rewarded.","ox":"X","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard I(B)","rat":"Best practice is the opposite: independent analysts should negotiate only a flat fee not linked to their conclusions or recommendations to avoid an incentive to bias the report."},{"i":"CFAOX-I-016","t":"Under Standard I(B), a member serving on the hiring side of a manager search may not solicit contributions to a favorite charity from firms seeking the mandate.","ox":"O","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard I(B)","rat":"The guidance states solicitations need not benefit the member personally to violate Standard I(B); soliciting charitable or political contributions can also be a violation."},{"i":"CFAOX-I-017","t":"A performance analyst who discovers that a manager altered composite construction to hide poor results may omit disclosure of the change in the final report if the manager is a large client of the firm.","ox":"X","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard I(B)","rat":"The guidance requires performance analysts to maintain independence and objectivity regardless of the size of an allocation or personal relationships, and to disclose such changes."},{"i":"CFAOX-I-018","t":"Standard I(B) requires that an analyst's investment recommendation, once committed to in a new-business pitch, guarantee a favorable rating for the prospective client.","ox":"X","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard I(B)","rat":"An analyst may agree to provide research coverage but must not commit the firm to a favorable recommendation; the recommendation must be based on independent, objective analysis."},{"i":"CFAOX-I-019","t":"Standard I(B) applies to credit rating agency analysts, who must abide by their agency's standards of conduct to prevent undue influence from a sponsoring company during the rating process.","ox":"O","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard I(B)","rat":"The guidance specifically addresses credit rating agency opinions and the need for firewalls and adherence to standards preventing undue sponsor influence."},{"i":"CFAOX-I-020","t":"A head of performance measurement may exclude an underperforming account from a composite whenever internal sales staff request it to protect a client relationship.","ox":"X","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard I(B)","rat":"The guidance states a member must maintain independence and refuse to exclude accounts invested under a strategy matching the composite, regardless of internal pressure."},{"i":"CFAMC-I-007","t":"An adviser tells a prospective client, \"I can guarantee you will earn 8% on this portfolio this year.\" This statement is MOST likely a violation of which standard?","c":"A","mc":{"s":"An adviser tells a prospective client, \"I can guarantee you will earn 8% on this portfolio this year.\" This statement is MOST likely a violation of which standard?","d":"","o":["Standard I(C) Misrepresentation, because guaranteeing a specific rate of return is misleading","Standard I(B) Independence and Objectivity, because the statement reflects sales pressure","No standard is violated as long as the adviser genuinely believes the return is achievable"],"a":1,"cite":"Standard I(C)","rat":"Standard I(C) specifically prohibits guaranteeing a particular rate of return or preservation of capital, since most investments carry inherently unpredictable returns."}},{"i":"CFAMC-I-008","t":"Yao creates a marketing presentation that misstates a composite's assets because of a typographical error, and the material is distributed before the mistake is caught. According to the guidance under Standard I(C), which statement is BEST?","c":"A","mc":{"s":"Yao creates a marketing presentation that misstates a composite's assets because of a typographical error, and the material is distributed before the mistake is caught. According to the guidance under Standard I(C), which statement is BEST?","d":"","o":["Yao violated Standard I(C) because any inaccurate figure in distributed materials is automatically a misrepresentation","Yao did not violate Standard I(C) because the error was unintentional, but he must still correct the error and stop distributing it","Yao violated Standard I(C) only if he refuses to correct the error after discovering it"],"a":2,"cite":"Standard I(C)","rat":"Because \"knowingly\" is required for a misrepresentation violation, an unintentional typographical error is not itself a violation, but the member must correct it and cease distribution once discovered."}},{"i":"CFAMC-I-009","t":"An analyst takes a research report written by another firm, changes the names on the cover page, and distributes it as her own original analysis. This is BEST described as a violation of Standard I(C) relating to:","c":"A","mc":{"s":"An analyst takes a research report written by another firm, changes the names on the cover page, and distributes it as her own original analysis. This is BEST described as a violation of Standard I(C) relating to:","d":"","o":["Plagiarism","Guaranteeing investment performance","Benchmark selection"],"a":1,"cite":"Standard I(C)","rat":"Standard I(C) prohibits plagiarism, defined as using material prepared by others without acknowledgment; presenting another's report as one's own original work is the clearest form of this violation."}},{"i":"CFAOX-I-021","t":"Standard I(C) prohibits members and candidates from knowingly making misrepresentations relating to investment analysis, recommendations, actions, or other professional activities.","ox":"O","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard I(C)","rat":"This restates the core text of Standard I(C)."},{"i":"CFAOX-I-022","t":"Standard I(C) prohibits stating or implying that a client will achieve in the future a rate of return that was generated in the past.","ox":"O","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard I(C)","rat":"The guidance specifically prohibits implying a past return will recur, as well as guaranteeing a specific future return."},{"i":"CFAOX-I-023","t":"Standard I(C) prohibits providing clients with information about investment products that have guarantees built into the structure of the product itself.","ox":"X","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard I(C)","rat":"The guidance explicitly states Standard I(C) does not prohibit describing products with guarantees built into their structure or backed by an institution."},{"i":"CFAOX-I-024","t":"A member who unintentionally distributes marketing material containing a typographical error has violated Standard I(C) regardless of intent.","ox":"X","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard I(C)","rat":"A misrepresentation under Standard I(C) requires that the member knew or should have known of the error; an unintentional, promptly corrected error is not itself a violation."},{"i":"CFAOX-I-025","t":"Members and candidates may distribute third-party outsourced research to clients as long as they do not represent themselves as its authors.","ox":"O","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard I(C)","rat":"The guidance permits distributing outsourced research provided members do not misrepresent authorship and disclose the source."},{"i":"CFAOX-I-026","t":"Research and models developed by an analyst while employed at a firm become the analyst's personal property, which the firm may not use after the analyst departs.","ox":"X","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard I(C)","rat":"The guidance states such work is the property of the firm, which retains the right to continue using it after the analyst leaves."},{"i":"CFAOX-I-027","t":"A former analyst who has left a firm may reissue a previously released firm report solely under his or her own name.","ox":"X","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard I(C)","rat":"The guidance explicitly states a member or candidate must not reissue a previously released report solely under his or her own name."},{"i":"CFAOX-I-028","t":"Presenting a hand-picked selection of only the highest-performing accounts as representative of a strategy's overall performance can constitute a misrepresentation under Standard I(C).","ox":"O","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard I(C)","rat":"The guidance identifies cherry-picking high-performing accounts as an example of misrepresenting performance history through omission."},{"i":"CFAOX-I-029","t":"Standard I(C) requires that a comparable benchmark always be disclosed alongside a strategy's performance in every case.","ox":"X","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard I(C)","rat":"The guidance notes some strategies may not lend themselves to an appropriate benchmark, so Standard I(C) does not always require one to be provided."},{"i":"CFAOX-I-030","t":"Switching security pricing providers solely because the new provider reports a higher valuation for an illiquid security is consistent with Standard I(C) as long as the new price is used consistently going forward.","ox":"X","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard I(C)","rat":"The guidance states changing providers must not be based solely on obtaining a higher reported value, since this practice of shopping for values can misrepresent a security's worth."},{"i":"CFAMC-I-010","t":"An environmental activist who also manages a mutual fund is repeatedly arrested for trespassing during nonviolent protests unrelated to her employer or the investment profession. According to Standard I(D) guidance, this conduct is BEST described as:","c":"A","mc":{"s":"An environmental activist who also manages a mutual fund is repeatedly arrested for trespassing during nonviolent protests unrelated to her employer or the investment profession. According to Standard I(D) guidance, this conduct is BEST described as:","d":"","o":["A violation, because any arrest automatically reflects adversely on a member's integrity","Generally not covered, because civil disobedience in support of personal beliefs does not reflect on professional reputation, integrity, or competence","A violation only of Standard I(A) Knowledge of the Law, not Standard I(D)"],"a":2,"cite":"Standard I(D)","rat":"The guidance states Standard I(D) is generally not meant to cover legal transgressions from acts of civil disobedience in support of personal beliefs."}},{"i":"CFAMC-I-011","t":"A retired CFA Institute member publishes an open letter using fabricated statistics to oppose a local casino project, signing the letter with reference to her CFA charter. According to the guidance under Standard I(D), her conduct is MOST likely:","c":"A","mc":{"s":"A retired CFA Institute member publishes an open letter using fabricated statistics to oppose a local casino project, signing the letter with reference to her CFA charter. According to the guidance under Standard I(D), her conduct is MOST likely:","d":"","o":["Not covered, because she is retired and the topic is unrelated to her former employer","A violation, because she used fabricated data and invoked her charter to lend credibility to her claims","A violation only if the letter is published in a professional, rather than local community, publication"],"a":2,"cite":"Standard I(D)","rat":"Because she explicitly identified herself as a CFA charterholder to add credibility, her use of fabricated statistics constitutes professional conduct and a violation of Standard I(D)."}},{"i":"CFAMC-I-012","t":"A junior analyst submits false medical documentation to obtain a disabled-person parking permit, unrelated to his employer or CFA Program involvement. According to the guidance under Standard I(D), this conduct is MOST likely:","c":"A","mc":{"s":"A junior analyst submits false medical documentation to obtain a disabled-person parking permit, unrelated to his employer or CFA Program involvement. According to the guidance under Standard I(D), this conduct is MOST likely:","d":"","o":["A clear violation, since dishonesty of any kind by a member or candidate always falls under Standard I(D)","Not a violation of Standard I(D), because it is unrelated to his professional activities or any use of CFA Institute affiliation","A violation, but only because it involves government officials rather than his employer"],"a":2,"cite":"Standard I(D)","rat":"The guidance notes that while dishonest, this conduct is tangential to employment and does not implicate the CFA Program or CFA Institute affiliation, so it falls outside professional conduct under Standard I(D)."}},{"i":"CFAOX-I-031","t":"Standard I(D) prohibits professional conduct involving dishonesty, fraud, or deceit, or any act that reflects adversely on a member's professional reputation, integrity, or competence.","ox":"O","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard I(D)","rat":"This restates the text of Standard I(D)."},{"i":"CFAOX-I-032","t":"Standard I(D) applies only to conduct that occurs physically in the member's workplace during business hours.","ox":"X","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard I(D)","rat":"The guidance extends professional activities to volunteer work, society events, writing outside the workplace, and any conduct that uses the CFA charter or membership, not just workplace conduct."},{"i":"CFAOX-I-033","t":"Becoming intoxicated during business hours in a way that affects one's ability to perform investment duties can be a violation of Standard I(D) even though it is not illegal.","ox":"O","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard I(D)","rat":"The guidance gives excessive drinking during business hours that impairs professional responsibilities as an example of conduct that damages trustworthiness or competence."},{"i":"CFAOX-I-034","t":"A member's volunteer service on a charity's board is never considered a professional activity under Standard I(D) because it is unpaid.","ox":"X","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard I(D)","rat":"The guidance treats volunteer board service undertaken because of one's status as an investment professional as a professional activity, and misconduct there can violate Standard I(D)."},{"i":"CFAOX-I-035","t":"Sexual harassment committed by a member while volunteering as an instructor for a local CFA Institute society's exam review course falls within professional conduct under Standard I(D).","ox":"O","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard I(D)","rat":"The guidance states such conduct is professional conduct because it occurs as part of the member's work with the local society and involves the use of membership."},{"i":"CFAOX-I-036","t":"Personal bankruptcy by a member or candidate is always, by itself, a violation of Standard I(D).","ox":"X","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard I(D)","rat":"The guidance states personal bankruptcy may not reflect on integrity or trustworthiness unless the circumstances involve fraudulent or deceitful conduct."},{"i":"CFAOX-I-037","t":"Fabricating statistics in an op-ed on an unrelated local political issue can violate Standard I(D) if the writer identifies themselves as a CFA charterholder to lend credibility to the claims.","ox":"O","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard I(D)","rat":"Using fabricated data while explicitly invoking one's charter to add credibility makes the conduct professional conduct and a violation, per the guidance."},{"i":"CFAOX-I-038","t":"Standard I(D) covers a candidate's dishonest personal conduct in obtaining a parking permit through fraudulent government paperwork, because dishonesty toward any government official is always professional conduct.","ox":"X","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard I(D)","rat":"The guidance treats this conduct as tangential to employment and unrelated to the CFA Program or CFA Institute affiliation, so it does not fall under professional conduct."},{"i":"CFAOX-I-039","t":"Members and candidates are encouraged to promote adoption of a code of ethics at their firms as a compliance practice to prevent general misconduct.","ox":"O","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard I(D)","rat":"The compliance practices guidance recommends encouraging firms to adopt a firm-wide code of ethics."},{"i":"CFAOX-I-040","t":"Civil disobedience arrests during nonviolent protests over personal beliefs, unrelated to a member's job, are generally covered by Standard I(D) because any arrest reflects poorly on integrity.","ox":"X","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard I(D)","rat":"The guidance states such acts of civil disobedience are generally not meant to be covered by Standard I(D) because they do not reflect on professional reputation, integrity, or competence."},{"i":"CFAMC-I-013","t":"Mifune, a financial planner, conducts thorough and appropriate research before recommending an insurance company with strong financials and a long track record; the company later goes bankrupt because of a previously unknown fraud by its CFO. According to the guidance under Standard I(E), Mifune:","c":"A","mc":{"s":"Mifune, a financial planner, conducts thorough and appropriate research before recommending an insurance company with strong financials and a long track record; the company later goes bankrupt because of a previously unknown fraud by its CFO. According to the guidance under Standard I(E), Mifune:","d":"","o":["Violated Standard I(E) because his recommendation ultimately caused client losses","Did not, by itself, violate Standard I(E), because a negative outcome alone does not indicate a lack of competence","Violated Standard I(E) only if he fails to compensate his clients for their losses"],"a":2,"cite":"Standard I(E)","rat":"The guidance states that lack of competence cannot necessarily be determined by an unsuccessful outcome, and thorough, appropriate research that fails to uncover concealed fraud does not by itself show incompetence."}},{"i":"CFAMC-I-014","t":"Halsey, a portfolio manager, has only read general newspaper articles about cryptocurrency and does not understand the differences among cryptocurrency products, yet purchases a heavily promoted cryptocurrency product for several clients to avoid appearing out of touch. This is BEST described as:","c":"A","mc":{"s":"Halsey, a portfolio manager, has only read general newspaper articles about cryptocurrency and does not understand the differences among cryptocurrency products, yet purchases a heavily promoted cryptocurrency product for several clients to avoid appearing out of touch. This is BEST described as:","d":"","o":["Consistent with Standard I(E), since general awareness from reputable sources satisfies the competence requirement","A violation of Standard I(E), because Halsey lacked sufficient knowledge of the asset before investing client funds in it","A violation of Standard I(B) only, since the issue relates to client pressure rather than competence"],"a":2,"cite":"Standard I(E)","rat":"The guidance concludes Halsey was not competent to invest in cryptocurrency given his limited knowledge, and hastily investing without understanding the asset violated Standard I(E)."}},{"i":"CFAMC-I-015","t":"Evans is promoted to director of research with new supervisory duties over four analysts. She studies the firm's ongoing research projects thoroughly but spends no time learning how to manage employees or the compliance requirements relating to supervision. According to the guidance under Standard I(E), Evans:","c":"A","mc":{"s":"Evans is promoted to director of research with new supervisory duties over four analysts. She studies the firm's ongoing research projects thoroughly but spends no time learning how to manage employees or the compliance requirements relating to supervision. According to the guidance under Standard I(E), Evans:","d":"","o":["Satisfied Standard I(E) because she mastered the technical research content of her new role","Violated Standard I(E) because her new role requires competence in supervisory skills and knowledge that she did not obtain","Did not violate Standard I(E), since supervisory competence is addressed only under Standard IV(C), not Standard I(E)"],"a":2,"cite":"Standard I(E)","rat":"The guidance states Evans must extend her competence to cover all responsibilities of her new supervisory role, including management and compliance knowledge, and her failure to do so violated Standard I(E)."}},{"i":"CFAOX-I-041","t":"Standard I(E) requires members and candidates to act with and maintain the competence necessary to fulfill their professional responsibilities.","ox":"O","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard I(E)","rat":"This restates the text of Standard I(E)."},{"i":"CFAOX-I-042","t":"Standard I(E) mandates that all members and candidates complete a specific, CFA Institute-designated continuing education program.","ox":"X","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard I(E)","rat":"The guidance states Standard I(E) contemplates ongoing professional development but does not mandate a particular continuing education program or plan."},{"i":"CFAOX-I-043","t":"An investment professional who experiences an unsuccessful or negative outcome is not thereby shown to lack competence under Standard I(E).","ox":"O","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard I(E)","rat":"The guidance explicitly states that competence cannot necessarily be determined by an unsuccessful or negative outcome."},{"i":"CFAOX-I-044","t":"Competence under Standard I(E) is determined solely by a member's or candidate's level of formal education.","ox":"X","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard I(E)","rat":"The guidance states competence is not limited to examining education level; a highly educated person may still lack competence in an unfamiliar area of practice."},{"i":"CFAOX-I-045","t":"Passing a required licensing examination is, by itself, always sufficient to demonstrate competence under Standard I(E).","ox":"X","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard I(E)","rat":"In the guidance's example, passing the licensing exam alone did not satisfy Standard I(E) because the individual had not actually learned the applicable rules for his new role."},{"i":"CFAOX-I-046","t":"When a member's professional responsibilities expand to include new supervisory duties, Standard I(E) requires the member to obtain the additional knowledge and skills needed for that supervisory role.","ox":"O","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard I(E)","rat":"The guidance states a member promoted to a supervisory role must extend competence to cover management and compliance responsibilities of the new position."},{"i":"CFAOX-I-047","t":"Standard I(E) requires only that competence be initially achieved; it does not require members to maintain that competence over time.","ox":"X","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard I(E)","rat":"The guidance states Standard I(E) imposes a duty not simply to achieve but also to maintain competence on an ongoing basis."},{"i":"CFAOX-I-048","t":"A member who thoroughly and appropriately researches an investment before recommending it has necessarily satisfied Standard I(E), even if the investment later fails because of fraud that was reasonably undetectable.","ox":"O","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard I(E)","rat":"Per the guidance's example, thorough and appropriate research that fails to uncover concealed fraud does not, by itself, indicate incompetence or a violation of Standard I(E)."},{"i":"CFAOX-I-049","t":"A portfolio manager who lacks understanding of a new asset class may satisfy Standard I(E) by investing client funds in it quickly, as long as the product is widely discussed in the media.","ox":"X","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard I(E)","rat":"The guidance's cryptocurrency example concludes that investing without adequate understanding of the asset violates Standard I(E), regardless of the product's popularity."},{"i":"CFAOX-I-050","t":"Knowledge, skills, and abilities required for competence under Standard I(E) are identical for every member and candidate regardless of professional role.","ox":"X","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard I(E)","rat":"The guidance states the knowledge, skills, and abilities necessary will vary according to the nature of each member's or candidate's professional duties."}],"7":[{"i":"CFAMC-VII-001","t":"After finishing an exam, a candidate posts publicly that the exam felt fair, that she believes she performed well, and that she was surprised a particular topic area was not tested at all. According to Standard VII(A) guidance, this post is BEST described as:","c":"A","mc":{"s":"After finishing an exam, a candidate posts publicly that the exam felt fair, that she believes she performed well, and that she was surprised a particular topic area was not tested at all. According to Standard VII(A) guidance, this post is BEST described as:","d":"","o":["Entirely acceptable, because expressing an opinion about the exam and one's own performance is not covered by Standard VII(A)","A violation, because revealing which topic areas were and were not covered on the exam discloses confidential exam content","Acceptable only if the post is made more than a year after the exam"],"a":2,"cite":"Standard VII(A)","rat":"The guidance's Rossi example distinguishes permissible personal opinions about difficulty and performance from the impermissible disclosure of specific topics covered or not covered, which compromises exam integrity."}},{"i":"CFAMC-VII-002","t":"A volunteer who chairs presentation scheduling for a CFA Institute local society, and who also works as an investor relations consultant, schedules only his own paying clients to present to the society, excluding other companies. According to Standard VII(A) guidance, this is BEST described as:","c":"A","mc":{"s":"A volunteer who chairs presentation scheduling for a CFA Institute local society, and who also works as an investor relations consultant, schedules only his own paying clients to present to the society, excluding other companies. According to Standard VII(A) guidance, this is BEST described as:","d":"","o":["Acceptable, since volunteer roles are not covered by Standard VII(A) unless the volunteer is paid by CFA Institute","A violation, because he used his volunteer position to benefit himself and his clients, compromising the reputation and integrity of CFA Institute","Acceptable, as long as the presenting companies are not required to pay a fee to present"],"a":2,"cite":"Standard VII(A)","rat":"The guidance's Ramirez example concludes that using a CFA Institute volunteer position for personal or client benefit compromises CFA Institute's reputation and integrity, violating Standard VII(A)."}},{"i":"CFAMC-VII-003","t":"Two Level I candidates discuss general study strategies and publicly available exam topic weightings while preparing together for the exam, without referencing specific exam questions from any actual exam administration. According to Standard VII(A) guidance, this activity is BEST described as:","c":"A","mc":{"s":"Two Level I candidates discuss general study strategies and publicly available exam topic weightings while preparing together for the exam, without referencing specific exam questions from any actual exam administration. According to Standard VII(A) guidance, this activity is BEST described as:","d":"","o":["A violation, because any discussion related to CFA exam preparation between candidates is prohibited","Not a violation, because Standard VII(A) does not prohibit candidates from discussing nonconfidential information in preparation for an exam","A violation only if the candidates are studying for different exam levels"],"a":2,"cite":"Standard VII(A)","rat":"The guidance explicitly states that Standard VII(A) does not prohibit candidates from discussing nonconfidential information or material with others or in study groups in preparation for an exam."}},{"i":"CFAOX-VII-001","t":"Standard VII(A) prohibits members and candidates from engaging in conduct that compromises the reputation or integrity of CFA Institute, the CFA designation, or the integrity, validity, or security of CFA Institute programs.","ox":"O","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard VII(A)","rat":"This restates the text of Standard VII(A)."},{"i":"CFAOX-VII-002","t":"Standard VII(A) does not prohibit candidates from discussing nonconfidential material with others, including in study groups, while preparing for an exam.","ox":"O","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard VII(A)","rat":"This is stated directly in the guidance's discussion of confidential CFA Institute information."},{"i":"CFAOX-VII-003","t":"Standard VII(A) prohibits members and candidates from ever expressing disagreement with CFA Institute's policies, procedures, or advocacy positions.","ox":"X","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard VII(A)","rat":"The guidance states members and candidates are free to express disagreement with CFA Institute on its policies, procedures, or advocacy positions; the prohibition applies to disclosing confidential exam content, not to opinions."},{"i":"CFAOX-VII-004","t":"Filing a fraudulent deferral request using an altered death certificate to postpone a CFA exam date violates Standard VII(A).","ox":"O","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard VII(A)","rat":"The guidance's Chiu example concludes such fraudulent conduct violates Standard VII(A) as well as Standard I(C)."},{"i":"CFAOX-VII-005","t":"Publicly discussing which specific topic areas were or were not tested on a recently completed exam is permitted under Standard VII(A) as long as no specific question text is quoted.","ox":"X","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard VII(A)","rat":"The guidance's Rossi example states revealing which topics were and were not covered on the exam is itself a violation of Standard VII(A), separate from quoting specific question text."},{"i":"CFAOX-VII-006","t":"A member who serves as an exam grader and later tells candidate colleagues which specific question he graded and how poorly candidates scored on it has violated Standard VII(A).","ox":"O","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard VII(A)","rat":"The guidance's Whitcomb example concludes disclosing such grading-related information violates Standard VII(A)."},{"i":"CFAOX-VII-007","t":"A member who serves on a CFA Institute technical standards committee may tell clients she will share confidential committee information early to help them gain a business advantage, as long as she is a committee volunteer.","ox":"X","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard VII(A)","rat":"The guidance's Warrenski example concludes using volunteer committee association and implying use of confidential information for client advantage violates Standard VII(A)."},{"i":"CFAOX-VII-008","t":"Sending test-preparation companies a summary of the specific questions a candidate found difficult on a recently completed exam is consistent with Standard VII(A), since the candidate did not directly profit from providing the information.","ox":"X","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard VII(A)","rat":"The guidance's Pena example states sharing specific exam questions with a test-prep company, even without personal profit, violates Standard VII(A) because it discloses confidential exam content."},{"i":"CFAOX-VII-009","t":"Bringing written notes into a computer-based testing center and reviewing them during the exam violates Standard VII(A) because it compromises the security and integrity of the exam.","ox":"O","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard VII(A)","rat":"The guidance's Yu example concludes this conduct violates testing rules and Standard VII(A)."},{"i":"CFAOX-VII-010","t":"Disruptive or threatening behavior toward exam proctors that disrupts other candidates' testing experience is outside the scope of Standard VII(A) because it does not involve disclosing exam content.","ox":"X","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard VII(A)","rat":"The guidance's Hermosa example concludes such conduct violates Standard VII(A) because it violates testing rules and compromises the security and integrity of the exam, even without disclosing content."},{"i":"CFAMC-VII-004","t":"An advertisement truthfully states that all of a firm's principals are CFA charterholders who passed all three exams on their first attempt, and links this fact to the claim that the firm's funds have achieved superior performance. According to Standard VII(B) guidance, this advertisement is BEST described as:","c":"A","mc":{"s":"An advertisement truthfully states that all of a firm's principals are CFA charterholders who passed all three exams on their first attempt, and links this fact to the claim that the firm's funds have achieved superior performance. According to Standard VII(B) guidance, this advertisement is BEST described as:","d":"","o":["Acceptable in full, because every individual statement in the advertisement is factually true","A violation, because linking passing the exams on the first attempt to superior investment performance implies an unsupported ability claim","Acceptable, because Standard VII(B) does not apply to firm-level marketing materials, only to individual biographies"],"a":2,"cite":"Standard VII(B)","rat":"The guidance's Zonder example states that while the underlying facts may be stated, linking them to superior investment performance or ability violates Standard VII(B)."}},{"i":"CFAMC-VII-005","t":"A charterholder whose CFA Institute membership has lapsed because he did not pay dues or file his Professional Conduct Statement continues to print business cards showing \"CFA\" after his name. According to Standard VII(B) guidance, this is:","c":"A","mc":{"s":"A charterholder whose CFA Institute membership has lapsed because he did not pay dues or file his Professional Conduct Statement continues to print business cards showing \"CFA\" after his name. According to Standard VII(B) guidance, this is:","d":"","o":["Acceptable, since he earned the charter permanently regardless of ongoing membership status","A violation, because a lapsed member no longer has the right to use the CFA designation until membership is reinstated","Acceptable, as long as he privately intends to reinstate his membership eventually"],"a":2,"cite":"Standard VII(B)","rat":"The guidance's Vasseur example concludes that continuing to use the designation after membership requirements lapse misrepresents charterholder status and violates Standard VII(B)."}},{"i":"CFAMC-VII-006","t":"A quantitative analyst posts an anonymous comment on an investor blog using the pseudonym \"Expert, CFA\" to avoid revealing his identity while discussing his professional work. According to Standard VII(B) guidance, this is BEST described as:","c":"A","mc":{"s":"A quantitative analyst posts an anonymous comment on an investor blog using the pseudonym \"Expert, CFA\" to avoid revealing his identity while discussing his professional work. According to Standard VII(B) guidance, this is BEST described as:","d":"","o":["Acceptable, since the underlying professional content he shared was accurate and helpful to investors","A violation, because attaching the CFA designation to a fictitious name or pseudonym used to hide one's identity is a misrepresentation","Acceptable, because Standard VII(B) applies only to formal written communications such as resumes and business cards"],"a":2,"cite":"Standard VII(B)","rat":"The guidance's Glass example states that tagging a pseudonym used to hide one's identity with the CFA designation is a misrepresentation and improper use of the designation."}},{"i":"CFAOX-VII-011","t":"Standard VII(B) prohibits members and candidates from misrepresenting or exaggerating the meaning or implications of CFA Institute membership, holding the CFA designation, or candidacy in the CFA Program.","ox":"O","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard VII(B)","rat":"This restates the text of Standard VII(B)."},{"i":"CFAOX-VII-012","t":"Standard VII(B) prohibits all factual statements about the positive benefits of earning the CFA designation.","ox":"X","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard VII(B)","rat":"The guidance explicitly states Standard VII(B) is not intended to prohibit factual statements about the positive benefits of the designation; it prohibits exaggerated or unsupported performance claims."},{"i":"CFAOX-VII-013","t":"A statement implying that CFA charterholders achieve superior investment performance results is an example of an improper reference under Standard VII(B).","ox":"O","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard VII(B)","rat":"The guidance's Exhibit 1 lists such a statement as an example of an improper reference."},{"i":"CFAOX-VII-014","t":"A candidate who truthfully states that they passed all three levels of the CFA exam in consecutive sittings has violated Standard VII(B) merely by stating this fact.","ox":"X","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard VII(B)","rat":"The guidance states that a true statement of passing each level in consecutive sittings is not itself a violation, since it is a statement of fact; only linking it to a claim of superior ability would violate the standard."},{"i":"CFAOX-VII-015","t":"A CFA Institute member whose membership has lapsed because dues were not paid may continue using the designation as long as they intend to reinstate membership eventually.","ox":"X","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard VII(B)","rat":"The guidance states a lapsed member must not present themselves as a member or charterholder and must remove designation references until membership is reactivated."},{"i":"CFAOX-VII-016","t":"A former CFA Institute member whose membership has lapsed may still state that they were a CFA Institute member in the past.","ox":"O","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard VII(B)","rat":"The guidance permits former members to state that they were members in the past or refer to the years they met membership requirements."},{"i":"CFAOX-VII-017","t":"A candidate who has passed one level of the CFA exam may state that they hold a partial CFA designation.","ox":"X","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard VII(B)","rat":"The guidance states candidates must never state or imply they have a partial designation as a result of passing one or more levels, except as authorized by CFA Institute."},{"i":"CFAOX-VII-018","t":"Candidates for the CFA designation are permitted to cite an expected date for completing and earning the charter in their communications.","ox":"X","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard VII(B)","rat":"The guidance states candidates must not cite an expected completion date for earning the charter, as final award is subject to meeting all requirements and Board approval."},{"i":"CFAOX-VII-019","t":"Using a pseudonym or fictitious online name tagged with the CFA designation to hide one's identity while posting professional commentary is a misrepresentation under Standard VII(B).","ox":"O","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard VII(B)","rat":"The guidance's Glass example concludes this practice is a misrepresentation and improper use of the designation."},{"i":"CFAOX-VII-020","t":"Standard VII(B) applies only to formal written documents such as resumes and business cards, not to informal communications like LinkedIn pages or email signatures.","ox":"X","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard VII(B)","rat":"The guidance states Standard VII(B) applies to any form of communication, explicitly including LinkedIn pages, email signatures, and oral statements, among others."}],"6":[{"i":"CFAMC-VI-001","t":"A portfolio manager's compensation structure changes to reward quarterly performance against peers, leading her to buy high-beta stocks for long-term pension accounts in a manner inconsistent with those clients' investment policy statements. According to Standard VI(A) guidance, she MOST likely violated the standard by:","c":"A","mc":{"s":"A portfolio manager's compensation structure changes to reward quarterly performance against peers, leading her to buy high-beta stocks for long-term pension accounts in a manner inconsistent with those clients' investment policy statements. According to Standard VI(A) guidance, she MOST likely violated the standard by:","d":"","o":["Accepting a performance-based bonus at all, since such arrangements are always prohibited","Failing to inform her clients of the changed compensation arrangement, which created a conflict between her incentives and the clients' stated objectives","Investing in high-beta stocks, which are inherently prohibited investments under Standard VI(A)"],"a":2,"cite":"Standard VI(A)","rat":"The guidance's Snead example concludes the violation was failing to inform clients of the compensation change that created a conflict with their IPS objectives, not the existence of performance-based pay itself."}},{"i":"CFAMC-VI-002","t":"A broker representative accepts undisclosed additional compensation from a stock promoter in exchange for selling that company's shares to his clients. According to Standard VI(A) guidance, the BEST practice would have been for the representative to:","c":"A","mc":{"s":"A broker representative accepts undisclosed additional compensation from a stock promoter in exchange for selling that company's shares to his clients. According to Standard VI(A) guidance, the BEST practice would have been for the representative to:","d":"","o":["Accept the payment and disclose it only if a client specifically asks about his compensation","Decline the additional compensation arrangement altogether to avoid the conflict of interest entirely","Accept the payment and disclose it only to his employer, since client disclosure is optional"],"a":2,"cite":"Standard VI(A)","rat":"The guidance states that, at minimum, disclosure to clients is required, but best practice is to avoid the conflict altogether by declining the additional compensation."}},{"i":"CFAMC-VI-003","t":"A chief investment officer moves a portion of a retirement fund's allocation to a firm founded by his former business school classmate, disclosing the change only in the annual report's routine manager listing, without disclosing the personal relationship to his employer. According to Standard VI(A) guidance, this is BEST described as:","c":"A","mc":{"s":"A chief investment officer moves a portion of a retirement fund's allocation to a firm founded by his former business school classmate, disclosing the change only in the annual report's routine manager listing, without disclosing the personal relationship to his employer. According to Standard VI(A) guidance, this is BEST described as:","d":"","o":["A violation, because he failed to disclose his personal relationship with the new manager to his employer so the conflict's impact could be assessed","Acceptable, because the change in external managers was ultimately reported in the fund's annual communications","Acceptable, because personal relationships with fund managers are not considered conflicts of interest under Standard VI(A)"],"a":1,"cite":"Standard VI(A)","rat":"The guidance's Papis example concludes the violation was failing to disclose the personal relationship to his employer, which would have allowed an assessment of whether it impaired his independence."}},{"i":"CFAOX-VI-001","t":"Standard VI(A) requires members and candidates to avoid or make full and fair disclosure of matters that could reasonably be expected to impair their independence and objectivity or interfere with duties to clients, prospective clients, and employers.","ox":"O","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard VI(A)","rat":"This restates the text of Standard VI(A)."},{"i":"CFAOX-VI-002","t":"Disclosures of conflicts of interest under Standard VI(A) must be prominent and communicated in plain language.","ox":"O","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard VI(A)","rat":"This is stated directly in the guidance on effective disclosure."},{"i":"CFAOX-VI-003","t":"Members and candidates beneficially own securities under Standard VI(A) only if they hold direct legal title to the shares in their own name.","ox":"X","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard VI(A)","rat":"The guidance defines beneficial ownership broadly to include a direct or indirect pecuniary interest, the power to vote shares, or the power to direct their disposition, not just direct legal title."},{"i":"CFAOX-VI-004","t":"Reportable conflicts to employers include ownership of stocks analyzed or recommended and participation on outside boards.","ox":"O","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard VI(A)","rat":"The guidance lists these as examples of reportable situations that must be promptly reported to employers."},{"i":"CFAOX-VI-005","t":"A member whose family member unexpectedly inherits a large ownership stake in a company the member covers has no disclosure obligation, since the member did not personally acquire the shares.","ox":"X","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard VI(A)","rat":"The guidance's Fargmon example states the member must, at minimum, disclose his wife's ownership to his employer and in his report."},{"i":"CFAOX-VI-006","t":"Board service by investment personnel can create conflicts of interest, including the risk of receiving material nonpublic information about the company.","ox":"O","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard VI(A)","rat":"The guidance identifies receipt of material nonpublic information as one of three basic conflicts arising from board service."},{"i":"CFAOX-VI-007","t":"Disclosure of a firm's broker/dealer market-making activities to clients is unnecessary under Standard VI(A) because such activities are a routine business function.","ox":"X","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard VI(A)","rat":"The guidance states such disclosure is required so clients understand that a trade might be made from or to the firm's proprietary account, giving the firm a special interest in the stock's price."},{"i":"CFAOX-VI-008","t":"A change in a portfolio manager's compensation structure that creates pressure inconsistent with clients' stated investment objectives must be disclosed to clients under Standard VI(A).","ox":"O","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard VI(A)","rat":"The guidance's Snead example concludes failing to inform clients of such a compensation change violated Standard VI(A)."},{"i":"CFAOX-VI-009","t":"Best practice for an underwriter's research analyst covering a company with which the firm has a long-standing investment banking relationship is to disclose that special relationship in the research report.","ox":"O","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard VI(A)","rat":"The guidance's Weiss example states such special relationships must be disclosed because they threaten the independence and objectivity of the report."},{"i":"CFAOX-VI-010","t":"Accepting undisclosed additional compensation from a third party for recommending its stock to clients is consistent with Standard VI(A) as long as the recommended stock later performs well.","ox":"X","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard VI(A)","rat":"The guidance's Carter example states this conduct violates Standard VI(A) because of the undisclosed conflict, regardless of the stock's subsequent performance."},{"i":"CFAMC-VI-004","t":"A portfolio manager manages her retirement-account clients, including an account for her own parents. To avoid any appearance of favoritism, she allocates IPO shares to all other clients first and gives her parents only the remaining shares, if any, that are suitable for them. According to Standard VI(B) guidance, this practice is BEST described as:","c":"A","mc":{"s":"A portfolio manager manages her retirement-account clients, including an account for her own parents. To avoid any appearance of favoritism, she allocates IPO shares to all other clients first and gives her parents only the remaining shares, if any, that are suitable for them. According to Standard VI(B) guidance, this practice is BEST described as:","d":"","o":["Consistent with Standard VI(B), since it clearly avoids any appearance of favoring family","A violation of Standard VI(B), because her parents, as fee-paying clients, are entitled to the same treatment as any other client rather than being systematically placed last","A violation only if her parents' account underperformed as a result of the allocation policy"],"a":2,"cite":"Standard VI(B)","rat":"The guidance's Toffler example concludes that systematically disadvantaging a family member's client account, even with good intentions, violates the duty to treat that account like any other client account."}},{"i":"CFAMC-VI-005","t":"A research analyst declines to recommend a stock for his employer's pension account because he wants to purchase the shares for his personal account first, before the recommendation is approved and the employer can act. This is BEST described as a violation of Standard VI(B) because:","c":"A","mc":{"s":"A research analyst declines to recommend a stock for his employer's pension account because he wants to purchase the shares for his personal account first, before the recommendation is approved and the employer can act. This is BEST described as a violation of Standard VI(B) because:","d":"","o":["Personal investing by analysts is prohibited entirely under Standard VI(B)","He used his knowledge of the stock's value to benefit personally before allowing his employer the opportunity to act on it","He failed to obtain preclearance approval before making the personal trade"],"a":2,"cite":"Standard VI(B)","rat":"The guidance's Long example states the violation arose from taking advantage of knowledge of the stock's value before allowing the employer to benefit from that information."}},{"i":"CFAMC-VI-006","t":"A firm's compliance policy requires employees to direct their brokers to send the firm duplicate confirmations of all personal securities transactions. According to the guidance under Standard VI(B), this requirement is BEST described as serving which purpose(s)?","c":"A","mc":{"s":"A firm's compliance policy requires employees to direct their brokers to send the firm duplicate confirmations of all personal securities transactions. According to the guidance under Standard VI(B), this requirement is BEST described as serving which purpose(s)?","d":"","o":["It has no real compliance value beyond deterring employees psychologically","It provides independent verification that reduces the likelihood of unethical behavior and allows tracking of personal investment activity","It is required only for employees who directly manage client portfolios, not for research staff"],"a":2,"cite":"Standard VI(B)","rat":"The guidance states duplicate confirmation requirements serve two purposes: signaling independent verification that reduces unethical behavior, and enabling tracking of personal investment flows."}},{"i":"CFAOX-VI-011","t":"Standard VI(B) requires that investment transactions for clients and employers have priority over transactions in which a member or candidate is the beneficial owner.","ox":"O","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard VI(B)","rat":"This restates the text of Standard VI(B)."},{"i":"CFAOX-VI-012","t":"Standard VI(B) prohibits members and candidates from ever co-investing in the same securities as their clients.","ox":"X","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard VI(B)","rat":"The guidance states co-investment with clients does not always create a conflict, and is sometimes appropriate, as long as clients are not disadvantaged."},{"i":"CFAOX-VI-013","t":"A member is never justified in making a personal transaction that runs counter to current recommendations being given to clients.","ox":"X","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard VI(B)","rat":"The guidance states a member may be justified in acting counter to client advice for personal financial reasons, such as needing to sell an asset."},{"i":"CFAOX-VI-014","t":"Family accounts that are also client accounts of the firm should be treated the same as other client accounts, neither favored nor disadvantaged because of the family relationship.","ox":"O","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard VI(B)","rat":"This is stated directly in the guidance on the impact on accounts with beneficial ownership."},{"i":"CFAOX-VI-015","t":"Blackout or restricted periods are used to prevent investment personnel from front-running client trades by trading for their own account before trading for clients.","ox":"O","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard VI(B)","rat":"This is stated directly in the guidance's discussion of blackout/restricted periods."},{"i":"CFAOX-VI-016","t":"Preclearance procedures for personal trades are designed to identify possible conflicts of interest before a trade is executed.","ox":"O","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard VI(B)","rat":"This is stated directly in the guidance's discussion of reporting requirements."},{"i":"CFAOX-VI-017","t":"Participation in equity IPOs by investment personnel creates no conflict-of-interest concerns as long as the personal purchase occurs after client trades are completed for the day.","ox":"X","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard VI(B)","rat":"The guidance states IPO participation raises conflicts around both taking attractive opportunities from clients and the appearance of receiving IPO access as an incentive; timing after client trades does not by itself resolve these concerns."},{"i":"CFAOX-VI-018","t":"A portfolio manager who routes hot IPO issues into a family member's account through a favored broker, while clients are unable to participate, has violated Standard VI(B).","ox":"O","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard VI(B)","rat":"The guidance's Baker example concludes this practice violates Standard VI(B), since client transactions must be given priority over personal or family transactions."},{"i":"CFAOX-VI-019","t":"A supervisor who fails to require an employee to complete required personal transaction disclosure forms is unrelated to Standard VI(B) and implicates only Standard I(A).","ox":"X","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard VI(B)","rat":"The guidance's Michaels/George example states the employee violated Standard VI(B) by prioritizing personal trades, while the supervisor separately violated Standard IV(C) for failing to enforce reporting requirements."},{"i":"CFAOX-VI-020","t":"A trading department head who closes a personal options position and establishes a new one shortly after an internal negative research presentation, before the report reaches clients, violates Standard VI(B).","ox":"O","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard VI(B)","rat":"The guidance's Riley example concludes trading ahead of giving customers the opportunity to act on the information violates Standard VI(B)."},{"i":"CFAMC-VI-007","t":"An employee in a bank's trust department receives internal compensation each time he refers a client to the bank's own brokerage or financial management department, but he does not disclose this arrangement to the clients he refers. According to Standard VI(C) guidance, this is BEST described as:","c":"A","mc":{"s":"An employee in a bank's trust department receives internal compensation each time he refers a client to the bank's own brokerage or financial management department, but he does not disclose this arrangement to the clients he refers. According to Standard VI(C) guidance, this is BEST described as:","d":"","o":["Acceptable, because Standard VI(C) applies only to referral payments from outside third parties, not internal interdepartmental arrangements","A violation, because Standard VI(C) does not distinguish between third-party referral payments and internal payments between departments of the same firm","Acceptable, as long as the referred department provides high-quality service to the client"],"a":2,"cite":"Standard VI(C)","rat":"The guidance's Handley example states Standard VI(C) applies equally to internal interdepartmental referral payments and external third-party referral fees, both of which must be disclosed."}},{"i":"CFAMC-VI-008","t":"A pension plan's hired consultant is contracted to represent the plan's best interest in selecting an investment manager, but he also charges a fee to any investment manager he recommends if that manager is awarded the mandate, without disclosing this fee. According to Standard VI(C) guidance, this arrangement is BEST described as:","c":"A","mc":{"s":"A pension plan's hired consultant is contracted to represent the plan's best interest in selecting an investment manager, but he also charges a fee to any investment manager he recommends if that manager is awarded the mandate, without disclosing this fee. According to Standard VI(C) guidance, this arrangement is BEST described as:","d":"","o":["Acceptable, because an independent review later confirmed the selected manager was objectively appropriate","A violation, because the undisclosed fee from the recommended manager implies a potential lack of objectivity in the consultant's recommendation","Acceptable, since consultants are not subject to Standard VI(C) unless they are CFA Institute members"],"a":2,"cite":"Standard VI(C)","rat":"The guidance's Arronski example concludes that failing to disclose the fee paid by the recommended firm violates Standard VI(C), regardless of whether the recommendation ultimately proved objectively sound."}},{"i":"CFAMC-VI-009","t":"According to the guidance under Standard VI(C), appropriate disclosure of a referral arrangement should include which of the following?","c":"A","mc":{"s":"According to the guidance under Standard VI(C), appropriate disclosure of a referral arrangement should include which of the following?","d":"","o":["Only a general statement that some referral compensation may exist, without specifics","The nature of the consideration or benefit, such as whether it is a flat fee, ongoing, or performance-based, together with its estimated dollar value","Only the identity of the party receiving the referral fee, without describing its structure or value"],"a":2,"cite":"Standard VI(C)","rat":"The guidance requires disclosure of the nature of the consideration or benefit, such as its structure and timing, along with its estimated dollar value."}},{"i":"CFAOX-VI-021","t":"Standard VI(C) requires members and candidates to disclose to their employer, clients, and prospective clients, as appropriate, any compensation or benefit received from or paid to others for the recommendation of products or services.","ox":"O","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard VI(C)","rat":"This restates the text of Standard VI(C)."},{"i":"CFAOX-VI-022","t":"Appropriate disclosure under Standard VI(C) should occur before a client or prospective client enters into a formal agreement for services.","ox":"O","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard VI(C)","rat":"The guidance states disclosure must be made before entry into any formal agreement for services."},{"i":"CFAOX-VI-023","t":"Standard VI(C) applies only to referral fees paid by outside third parties and does not cover internal referral payments made between departments of the same firm.","ox":"X","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard VI(C)","rat":"The guidance explicitly states Standard VI(C) does not distinguish between third-party payments and internal interdepartmental payments; both must be disclosed."},{"i":"CFAOX-VI-024","t":"Consideration under Standard VI(C) includes only cash fees; noncash or soft-dollar benefits are excluded from the disclosure requirement.","ox":"X","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard VI(C)","rat":"The guidance states consideration includes all fees, whether paid in cash, soft dollars, or in kind."},{"i":"CFAOX-VI-025","t":"A member who fails to disclose that a referral arrangement exists between the firm that referred a prospective client and the member's own firm violates Standard VI(C), because the omission prevents the client from critically evaluating the recommendation.","ox":"O","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard VI(C)","rat":"The guidance's White/Lewis Brothers example concludes such nondisclosure prevents the prospective client from reassessing the recommendation and violates Standard VI(C)."},{"i":"CFAOX-VI-026","t":"A portfolio manager who directs a large share of trading commissions to a broker that, in return, recommends the manager's services to its clients has no disclosure obligation as long as the broker's pricing remains competitive.","ox":"X","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard VI(C)","rat":"The guidance's Roberts/Naushon example states such an arrangement must be disclosed to both the employer and clients, regardless of pricing competitiveness."},{"i":"CFAOX-VI-027","t":"A consultant hired to represent a pension plan's best interest in an investment manager search must disclose any fee he separately receives from a manager he recommends if that manager is hired.","ox":"O","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard VI(C)","rat":"The guidance's Arronski example confirms this disclosure obligation applies to such consultants."},{"i":"CFAOX-VI-028","t":"Members and candidates who participate in an approved referral fee program should provide their employer with regular updates, at least quarterly, on compensation received through such arrangements.","ox":"O","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard VI(C)","rat":"This is stated directly in the compliance practices guidance for Standard VI(C)."},{"i":"CFAOX-VI-029","t":"Standard VI(C) requires disclosure only when a referral fee is expected to be substantial; small or nominal referral payments are exempt from disclosure.","ox":"X","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard VI(C)","rat":"The guidance does not create a materiality threshold exempting small referral payments; all such compensation, consideration, or benefit must be disclosed as appropriate."},{"i":"CFAOX-VI-030","t":"Disclosure of a referral fee arrangement to the employer alone, without disclosure to the client, always satisfies the requirements of Standard VI(C).","ox":"X","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard VI(C)","rat":"The guidance requires disclosure to employer, clients, and prospective clients as appropriate; several examples show that failing to disclose to the client specifically constitutes a violation."}],"5":[{"i":"CFAMC-V-001","t":"A member is part of a research group whose published report reflects the group's consensus view, which differs somewhat from the member's own opinion. According to the guidance under Standard V(A), the member:","c":"A","mc":{"s":"A member is part of a research group whose published report reflects the group's consensus view, which differs somewhat from the member's own opinion. According to the guidance under Standard V(A), the member:","d":"","o":["Must always dissociate from any group report that does not fully match his personal opinion","Does not need to dissociate from the report if he believes the consensus view has a reasonable, adequate, independent, and objective basis","May allow his name to remain on the report only if he first obtains the client's written consent"],"a":2,"cite":"Standard V(A)","rat":"The guidance states a member need not dissociate from a group report, even if it does not reflect his personal view, as long as he believes the consensus has a reasonable and adequate basis and is independent and objective."}},{"i":"CFAMC-V-002","t":"A portfolio manager at a large firm uses a third-party data vendor that was selected after the firm's senior managers conducted their own due diligence on data providers. According to Standard V(A) guidance, the portfolio manager:","c":"A","mc":{"s":"A portfolio manager at a large firm uses a third-party data vendor that was selected after the firm's senior managers conducted their own due diligence on data providers. According to Standard V(A) guidance, the portfolio manager:","d":"","o":["Must independently re-conduct full due diligence on the vendor before using any of its data, regardless of the firm's prior review","May use the vendor's information in good faith, assuming the firm's due diligence process was adequate, absent reason to question its validity","May never rely on third-party data under Standard V(A) without first obtaining direct client consent"],"a":2,"cite":"Standard V(A)","rat":"The guidance states members without a choice of data source may rely in good faith on their firm's due diligence process, absent reason to question the research's validity."}},{"i":"CFAMC-V-003","t":"According to the guidance under Standard V(A), individuals who develop new quantitative investment models are expected to exhibit which level of diligence relative to the individuals who later use the models' output?","c":"A","mc":{"s":"According to the guidance under Standard V(A), individuals who develop new quantitative investment models are expected to exhibit which level of diligence relative to the individuals who later use the models' output?","d":"","o":["A lower level of diligence, since model developers rely on the eventual users to catch any errors","The same level of diligence as the eventual users, since Standard V(A) does not distinguish between developers and users","A higher level of diligence, including thorough testing of the model before it is distributed for use"],"a":3,"cite":"Standard V(A)","rat":"The guidance states individuals who create new quantitative models must exhibit a higher level of diligence than those who ultimately use the analytical output, including thorough testing before distribution."}},{"i":"CFAOX-V-001","t":"Standard V(A) requires members and candidates to have a reasonable and adequate basis, supported by appropriate research and investigation, for any investment analysis, recommendation, or action.","ox":"O","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard V(A)","rat":"This restates the text of Standard V(A)."},{"i":"CFAOX-V-002","t":"The level of research and diligence required by Standard V(A) is identical for every product, security, or service, regardless of its nature.","ox":"X","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard V(A)","rat":"The guidance states the necessary level of research and analysis will differ with the product, security, or service being offered."},{"i":"CFAOX-V-003","t":"Information or data sourced from blogs or social media may require a greater level of review than information from more established research organizations.","ox":"O","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard V(A)","rat":"This is stated directly in the guidance's discussion of information sources."},{"i":"CFAOX-V-004","t":"Members and candidates who rely on secondary or third-party research must make reasonable and diligent efforts to determine that the research is sound before relying on it.","ox":"O","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard V(A)","rat":"This is stated directly in the guidance regarding secondary and third-party research."},{"i":"CFAOX-V-005","t":"Members and candidates should continue to rely on third-party research even after they have reason to suspect the source is biased or unreliable, as long as it was originally vetted by the firm.","ox":"X","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard V(A)","rat":"The guidance states that if a member has reason to suspect research is biased, unreliable, or deficient, the member must not rely on that information."},{"i":"CFAOX-V-006","t":"Individuals who develop new quantitative investment models must exhibit a higher level of diligence than the individuals who ultimately use the models' output.","ox":"O","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard V(A)","rat":"This is explicitly stated in the guidance's discussion of quantitative research and techniques."},{"i":"CFAOX-V-007","t":"Standard V(A) requires members and candidates who use quantitative models to become technical experts capable of building the model themselves.","ox":"X","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard V(A)","rat":"The guidance states members are not required to become experts in every technical aspect of a model, but must understand its assumptions and limitations."},{"i":"CFAOX-V-008","t":"Standard V(A) requires the same level of diligence in selecting an external adviser or subadviser as in reviewing an individual investment opportunity.","ox":"O","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard V(A)","rat":"The guidance states members must review external advisers and subadvisers as diligently as they review individual investment opportunities."},{"i":"CFAOX-V-009","t":"A member on a research team may allow his name to remain on a group report reflecting a consensus view that differs somewhat from his own opinion, as long as he believes that consensus has a reasonable and adequate, independent, and objective basis.","ox":"O","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard V(A)","rat":"The guidance on group research states the member need not dissociate from the report under these conditions."},{"i":"CFAOX-V-010","t":"A well-informed and diligently prepared investment recommendation eliminates all downside risk for the resulting investment.","ox":"X","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard V(A)","rat":"The guidance states that even a well-informed recommendation carries downside risk, since decisions are based only on information available at the time."},{"i":"CFAMC-V-004","t":"A firm charges clients a quarterly fee based on the market value of assets under management, making it impossible to state an exact dollar amount in advance. According to Standard V(B) guidance, the firm's disclosure obligation regarding costs is BEST described as:","c":"A","mc":{"s":"A firm charges clients a quarterly fee based on the market value of assets under management, making it impossible to state an exact dollar amount in advance. According to Standard V(B) guidance, the firm's disclosure obligation regarding costs is BEST described as:","d":"","o":["Not required, since the exact dollar amount cannot be determined in advance","Satisfied by providing a reasonable amount of detail about the cost structure, even without a specific dollar figure","Satisfied only if the firm also discloses its own internal cost of providing the service"],"a":2,"cite":"Standard V(B)","rat":"The guidance states members must provide a reasonable amount of detail about client costs but are not required to provide a specific dollar amount, using an asset-based fee as the example."}},{"i":"CFAMC-V-005","t":"An analyst publishes a report containing earnings estimates and forward-looking dividend expectations without indicating that these figures are projections rather than established facts. This is MOST likely a violation of Standard V(B) because it fails to:","c":"A","mc":{"s":"An analyst publishes a report containing earnings estimates and forward-looking dividend expectations without indicating that these figures are projections rather than established facts. This is MOST likely a violation of Standard V(B) because it fails to:","d":"","o":["Disclose the costs associated with the analyst's services","Distinguish between fact and opinion in the presentation of investment analysis","Disclose the use of an external adviser in the investment process"],"a":2,"cite":"Standard V(B)","rat":"The guidance states violations occur when members fail to separate the past from the future by not identifying earnings estimates or forward-looking figures as opinions subject to future circumstances."}},{"i":"CFAMC-V-006","t":"A member believes his firm's standard client disclosures about fees are flawed and insufficient to meet the requirements of Standard V(B). According to the guidance, the member should MOST appropriately:","c":"A","mc":{"s":"A member believes his firm's standard client disclosures about fees are flawed and insufficient to meet the requirements of Standard V(B). According to the guidance, the member should MOST appropriately:","d":"","o":["Use the firm's disclosures as provided, since client-facing members bear no personal responsibility once firm policy dictates disclosure content","Supplement the firm's disclosures where possible and, if unable to rectify them, document objections and take steps to dissociate from the activity","Simply avoid providing any cost disclosures at all rather than use ones he believes are flawed"],"a":2,"cite":"Standard V(B)","rat":"The guidance states members should supplement inadequate firm-generated disclosures when possible and, if unable to do so, document their objections and take steps to dissociate."}},{"i":"CFAOX-V-011","t":"Standard V(B) requires members and candidates to disclose to clients the nature of services provided and information about the costs associated with those services.","ox":"O","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard V(B)","rat":"This restates one of the core requirements of Standard V(B)."},{"i":"CFAOX-V-012","t":"Standard V(B) requires members and candidates to disclose the specific dollar amount clients will pay for services, even when fees are based on a formula such as a percentage of assets under management.","ox":"X","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard V(B)","rat":"The guidance states members are not required to provide a specific dollar amount, using a market-value-based quarterly fee as an example where this is not possible in advance."},{"i":"CFAOX-V-013","t":"A member may rely on a sophisticated client's presumed understanding of the investment process as a reason to omit required disclosures under Standard V(B).","ox":"X","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard V(B)","rat":"The guidance explicitly states members may not rely on client sophistication as a reason to withhold required information, though the information may be tailored to the client's sophistication."},{"i":"CFAOX-V-014","t":"Disclosure obligations under Standard V(B) are limited to costs charged directly by the member's own firm and do not extend to costs from affiliates or third parties.","ox":"X","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard V(B)","rat":"The guidance states disclosures must cover all costs associated with the investment services and products, including those from affiliates, related entities, or third parties."},{"i":"CFAOX-V-015","t":"Members and candidates must notify clients when significant changes occur in the risk characteristics of a security or investment strategy.","ox":"O","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard V(B)","rat":"This is stated directly in the guidance's discussion of identifying risks and limitations."},{"i":"CFAOX-V-016","t":"A member who has no knowledge of a particular risk at the time a recommendation is made, and which later triggers a loss, necessarily breaches Standard V(B).","ox":"X","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard V(B)","rat":"The guidance states members cannot be expected to disclose risks they are unaware of, and lack of knowledge of a risk may indicate a diligence issue rather than a breach of Standard V(B) specifically."},{"i":"CFAOX-V-017","t":"Standard V(B) requires that earnings estimates and forward-looking dividend expectations be clearly identified as opinions rather than established facts.","ox":"O","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard V(B)","rat":"The guidance's fact-versus-opinion discussion requires this distinction to be made clear."},{"i":"CFAOX-V-018","t":"Members and candidates must inform clients when their firm's investment process involves the use of external advisers to manage portions of client assets.","ox":"O","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard V(B)","rat":"The guidance requires disclosure of the use of external advisers as part of the investment process."},{"i":"CFAOX-V-019","t":"Standard V(B) imposes an affirmative duty on all members and candidates, including those without any client-facing responsibilities, to ensure that colleagues provide adequate disclosures to clients.","ox":"X","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard V(B)","rat":"The guidance states this standard generally affects only client-facing members and does not extend the duty to non-client-facing team members."},{"i":"CFAOX-V-020","t":"If a firm's standard disclosures are inadequate and cannot be corrected, a member should document objections and take steps to dissociate from the activity.","ox":"O","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard V(B)","rat":"This is the recommended course of action stated in the guidance's discussion of the manner of disclosures."},{"i":"CFAMC-V-007","t":"A portfolio manager followed a client's investment policy statement, which called for a 35% benchmark allocation to technology stocks that later underperformed. According to Standard V(C) guidance, to demonstrate compliance the manager should have retained:","c":"A","mc":{"s":"A portfolio manager followed a client's investment policy statement, which called for a 35% benchmark allocation to technology stocks that later underperformed. According to Standard V(C) guidance, to demonstrate compliance the manager should have retained:","d":"","o":["Only the client's final account statements showing the resulting investment losses","The client's IPS, records showing the process was explained to the client, and evidence the IPS was updated regularly","Nothing, because Standard V(C) applies only to decisions that lead to a change in position"],"a":2,"cite":"Standard V(C)","rat":"The guidance's Lindstrom example concludes that retaining the client's IPS, evidence the process was explained, and records of regular IPS updates would demonstrate compliance with Standard V(C)."}},{"i":"CFAMC-V-008","t":"A former analyst wants to use a research report he created at his prior firm in his work for a new employer, but he no longer has access to the supporting documentation, which remained with the former employer. According to Standard V(C) guidance, he should MOST appropriately:","c":"A","mc":{"s":"A former analyst wants to use a research report he created at his prior firm in his work for a new employer, but he no longer has access to the supporting documentation, which remained with the former employer. According to Standard V(C) guidance, he should MOST appropriately:","d":"","o":["Use the report as originally written, since he personally created its content","Recreate the supporting records at the new firm, without using sources obtained from the previous employer without permission","Request the former employer's client list to help recreate the supporting documentation"],"a":2,"cite":"Standard V(C)","rat":"The guidance requires members to recreate supporting records at a new firm without using sources from the previous employer without permission, since the original records remain the former firm's property."}},{"i":"CFAMC-V-009","t":"In the absence of any applicable regulatory requirement or firm policy specifying a record retention period, Standard V(C) guidance recommends maintaining records for at least:","c":"A","mc":{"s":"In the absence of any applicable regulatory requirement or firm policy specifying a record retention period, Standard V(C) guidance recommends maintaining records for at least:","d":"","o":["One year","Seven years","Twenty-five years"],"a":2,"cite":"Standard V(C)","rat":"The guidance states that in the absence of regulatory or firm guidance, CFA Institute recommends maintaining records for at least seven years."}},{"i":"CFAOX-V-021","t":"Standard V(C) requires members and candidates to develop and maintain appropriate records supporting their investment analyses, recommendations, actions, and related communications.","ox":"O","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard V(C)","rat":"This restates the text of Standard V(C)."},{"i":"CFAOX-V-022","t":"The record retention requirement under Standard V(C) applies only to decisions that result in a change of position, not to reviews that lead to no action.","ox":"X","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard V(C)","rat":"The guidance states the retention requirement applies to buy or sell decisions as well as to reviews undertaken that do not lead to a change in position."},{"i":"CFAOX-V-023","t":"Electronic communications such as emails, text messages, and social media posts are examples of formats that must be retained under Standard V(C).","ox":"O","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard V(C)","rat":"The guidance lists these as examples of electronic or digital formats for records that must be retained."},{"i":"CFAOX-V-024","t":"Records created as part of a member's professional activity on behalf of an employer are generally considered the personal property of the member who created them.","ox":"X","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard V(C)","rat":"The guidance states such records are, as a general matter, the property of the firm, not the individual member."},{"i":"CFAOX-V-025","t":"A departing member may take copies of supporting research records to a new employer without the previous employer's consent, as long as the member authored the original work.","ox":"X","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard V(C)","rat":"The guidance states members cannot take firm property, including supporting records of their work, to a new employer without the previous employer's express consent."},{"i":"CFAOX-V-026","t":"If a member cannot access the supporting documentation for research created at a former firm, the member must recreate the supporting records at the new firm rather than reuse the unsupported report.","ox":"O","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard V(C)","rat":"The guidance states members must not use historical recommendations without supporting documentation and must recreate records at the new firm instead."},{"i":"CFAOX-V-027","t":"Complying with applicable regulatory and firm record retention requirements is sufficient to satisfy Standard V(C).","ox":"O","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard V(C)","rat":"The guidance states fulfilling regulatory and firm requirements satisfies the requirements of Standard V(C)."},{"i":"CFAOX-V-028","t":"In the absence of regulatory guidance or firm policy on record retention periods, CFA Institute recommends retaining records for at least seven years.","ox":"O","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard V(C)","rat":"This figure is stated directly in the guidance."},{"i":"CFAOX-V-029","t":"The primary responsibility to maintain records supporting investment action generally rests with individual members rather than with the firm.","ox":"X","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard V(C)","rat":"The guidance states this responsibility generally rests with the firm rather than individuals, though members should still archive supporting materials."},{"i":"CFAOX-V-030","t":"A research analyst who relies on interviews, on-site visits, and secondary research from other analysts is required to document and keep copies of all such information supporting the report.","ox":"O","y":null,"e":"CFA Level I","qn":null,"c":"A","cite":"Standard V(C)","rat":"The guidance's Young example concludes that failure to maintain files supporting all sources used in a report, including third-party research, would violate Standard V(C)."}]};
window.PAIRS=[{"n":3,"s":0.323,"o":{"i":"CFAOX-III-001","t":"Standard III(A) requires members and candidates to act for the benefit of clients and place client interests before those of their employer or themselves.","y":null,"e":"CFA Level I"},"x":{"i":"CFAOX-III-008","t":"Standard III(A) requires members and candidates to vote every proxy in every instance, regardless of cost or benefit to the client.","y":null,"e":"CFA Level I"}},{"n":1,"s":0.611,"o":{"i":"CFAOX-I-001","t":"Standard I(A) requires members and candidates to comply with the stricter of applicable law and the Code and Standards when the two conflict.","y":null,"e":"CFA Level I"},"x":{"i":"CFAOX-I-002","t":"Standard I(A) requires members and candidates to comply with whichever of applicable law or the Code and Standards is less restrictive.","y":null,"e":"CFA Level I"}},{"n":7,"s":0.301,"o":{"i":"CFAOX-VII-011","t":"Standard VII(B) prohibits members and candidates from misrepresenting or exaggerating the meaning or implications of CFA Institute membership, holding the CFA designation, or candidacy in the CFA Program.","y":null,"e":"CFA Level I"},"x":{"i":"CFAOX-VII-003","t":"Standard VII(A) prohibits members and candidates from ever expressing disagreement with CFA Institute's policies, procedures, or advocacy positions.","y":null,"e":"CFA Level I"}},{"n":5,"s":0.305,"o":{"i":"CFAOX-V-011","t":"Standard V(B) requires members and candidates to disclose to clients the nature of services provided and information about the costs associated with those services.","y":null,"e":"CFA Level I"},"x":{"i":"CFAOX-V-012","t":"Standard V(B) requires members and candidates to disclose the specific dollar amount clients will pay for services, even when fees are based on a formula such as a percentage of assets under management.","y":null,"e":"CFA Level I"}}];
